window.BraidData.sources["BraidStudio"] = {"module":"BraidStudio","files":[{"path":"Sources/BraidStudio/Backend.swift","lines":308,"bytes":15351,"header":{"lines":[1,15],"what":[8,12],"pin":[13,14],"in":null,"out":null},"marks":[],"first":1647,"scopes":[["P","StudioBackend",null,"public",21,21,[21,51],24,null,-1,0],["f","submit",["_"],"",22,22,null,22,null,0,1],["f","shutdown",[],"",23,23,null,23,null,0,1],["S","StudioOptions",null,"public",26,26,[26,38],46,null,-1,0],["i","init",[],"public",35,35,[35,18],35,null,3,8],["f","defaultDemoRoot",["executable"],"public static",38,38,[38,112],45,[37,37],3,0],["E","StudioFailure",null,"",49,49,[49,19],58,[48,48],-1,0,[]],["f","describe",["_"],"static",50,50,[50,57],57,null,6,0],["C","SharedBraid",null,"final",62,62,[62,45],80,[60,61],-1,0],["v","layouts",null,"",68,68,[68,39],68,null,8,8],["f","setLayout",["_","for"],"",69,69,[69,61],69,null,8,8],["v","attached",null,"",71,71,[71,27],74,null,8,0],["v","tokenizerFolder",null,"",76,76,[76,30],79,null,8,0],["C","LiveBackend",null,"public final",82,82,[82,67],198,null,-1,0],["i","init",["options","post"],"public",88,88,[88,89],92,null,13,0],["i","init",["options","mailbox"],"public convenience",94,94,[94,83],96,null,13,0],["f","submit",["_"],"public",98,98,[98,41],127,null,13,0],["f","shutdown",[],"public",129,129,[129,33],129,null,13,8],["f","label",["_"],"static",131,131,[131,50],146,null,13,0],["f","perform",["_"],"",148,148,[148,48],178,null,13,0],["f","verify",["_"],"",182,182,[182,35],197,[180,181],13,0],["E","Sessions",null,"",200,200,[200,14],208,null,-1,0,[]],["f","list",["in"],"static",202,202,[202,56],207,[201,201],21,0],["E","SessionReplayer",null,"",211,211,[211,21],232,[210,210],-1,0,[]],["f","replay",["_","delay","post","shouldStop"],"static",212,212,[212,140],231,null,23,0],["E","Examples",null,"",235,235,[235,14],259,[234,234],-1,0,[]],["f","load",["area","attached","perThread"],"static",236,236,[236,97],258,null,25,0],["E","AIIProbe",null,"",262,262,[262,14],308,[261,261],-1,0,[]],["f","status",["demoRoot","environment"],"static",265,265,[265,126],276,null,27,0],["f","home",["named","path","demoRoot"],"static",278,278,[278,90],307,null,27,0]],"text":"//\n//  Backend.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where the studio's jobs run. `LiveBackend` sends the MLX jobs (start, generate, attach\n//        and detach, create a Thread) to the one MLX worker thread and runs everything else — the\n//        AII, the doctor, the sessions list, replaying a saved session, verifying one, the example\n//        prompts — as detached tasks. Both backends replay a session through `SessionReplayer`,\n//        posting its log lines, so a saved session renders exactly as the live one did.\n//  PIN:  Every job reports `jobStarted`, then `jobFinished` or `jobFailed`, with the CLI's failure\n//        type and exit codes.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\npublic protocol StudioBackend: AnyObject, Sendable {\n    func submit(_ job: StudioJob)\n    func shutdown() async\n}\n\npublic struct StudioOptions: Sendable {\n    /// The work area, when one resolved; `workAreaProblem` says why it did not.\n    public var workArea: WorkArea?\n    public var workAreaProblem: String?\n    /// Replay a recorded session from this directory instead of running MLX.\n    public var fixtures: URL?\n    /// Where `braid aii create` puts demo AII homes: `<repo>/aii`.\n    public var demoRoot: URL = StudioOptions.defaultDemoRoot()\n\n    public init() {}\n\n    /// The repository root, found from the running binary (`.build/…/braid`); the working directory otherwise.\n    public static func defaultDemoRoot(executable: URL = URL(fileURLWithPath: CommandLine.arguments[0])) -> URL {\n        var url = executable.resolvingSymlinksInPath().deletingLastPathComponent()\n        for _ in 0..<8 {\n            if FileManager.default.fileExists(atPath: url.appendingPathComponent(\"Package.swift\").path) { return DemoHomes.root(repository: url) }\n            url.deleteLastPathComponent()\n        }\n        return DemoHomes.root(repository: URL(fileURLWithPath: FileManager.default.currentDirectoryPath, isDirectory: true))\n    }\n}\n\n/// The failure a job reports: BraidFailure as it is, the braid's own errors mapped to data errors.\nenum StudioFailure {\n    static func describe(_ error: Error) -> BraidFailure {\n        if let failure = error as? BraidFailure { return failure }\n        if error is CancellationError { return BraidFailure(\"cancelled\", code: .interrupted) }\n        if let error = error as? ClusterError { return BraidFailure(error.description, code: .data) }\n        if let error = error as? Conformance.Failure { return BraidFailure(error.description, code: .data) }\n        if let error = error as? SessionReader.Failure { return BraidFailure(error.description, code: .data) }\n        return BraidFailure(\"\\(error)\", code: .internalError)\n    }\n}\n\n/// What the worker loaded that the backend's jobs read: the Threads' index layouts (for verify),\n/// the tokenizer folder, the names attached. Touched under its lock.\nfinal class SharedBraid: @unchecked Sendable {\n    private let lock = NSLock()\n    private var storedLayouts: [String: IndexLayout] = [:]\n    private var storedAttached: [String] = []\n    private var storedTokenizerFolder: URL?\n\n    var layouts: [String: IndexLayout] { lock.withLock { storedLayouts } }\n    func setLayout(_ layout: IndexLayout?, for name: String) { lock.withLock { storedLayouts[name] = layout } }\n\n    var attached: [String] {\n        get { lock.withLock { storedAttached } }\n        set { lock.withLock { storedAttached = newValue } }\n    }\n\n    var tokenizerFolder: URL? {\n        get { lock.withLock { storedTokenizerFolder } }\n        set { lock.withLock { storedTokenizerFolder = newValue } }\n    }\n}\n\npublic final class LiveBackend: StudioBackend, @unchecked Sendable {\n    let options: StudioOptions\n    let post: @Sendable (StudioEvent) -> Void\n    let shared = SharedBraid()\n    let worker: MLXWorker\n\n    public init(options: StudioOptions, post: @escaping @Sendable (StudioEvent) -> Void) {\n        self.options = options\n        self.post = post\n        worker = MLXWorker(options: options, shared: shared, post: post)\n    }\n\n    public convenience init(options: StudioOptions, mailbox: Mailbox<StudioEvent>) {\n        self.init(options: options, post: { mailbox.post($0) })\n    }\n\n    public func submit(_ job: StudioJob) {\n        switch job {\n        case .cancel:\n            worker.request(.cancel)\n            return\n        case .attach(let name):\n            worker.request(.attach(name))\n            return\n        case .detach(let name):\n            worker.request(.detach(name))\n            return\n        default:\n            break\n        }\n        guard let kind = job.kind else { return }\n        if kind.isMLX {\n            worker.enqueue(job)\n            return\n        }\n        let post = self.post\n        Task.detached { [self] in\n            post(.jobStarted(kind, Self.label(job)))\n            do {\n                try await perform(job)\n                post(.jobFinished(kind))\n            } catch {\n                post(.jobFailed(kind, StudioFailure.describe(error)))\n            }\n        }\n    }\n\n    public func shutdown() async { worker.stop() }\n\n    static func label(_ job: StudioJob) -> String {\n        switch job {\n        case .start: return \"starting the braid\"\n        case .generate(let request): return \"asking: \\(request.prompt.prefix(40))\"\n        case .attach(let name): return \"attaching \\(name)\"\n        case .detach(let name): return \"detaching \\(name)\"\n        case .createThread(let request): return \"creating \\(request.name)\"\n        case .examples: return \"reading example prompts\"\n        case .verify: return \"verifying the session\"\n        case .sessions: return \"listing sessions\"\n        case .openSession(let url): return \"replaying \\(url.lastPathComponent)\"\n        case .aii: return \"detecting the AII\"\n        case .doctor: return \"running the checks\"\n        case .cancel: return \"cancelling\"\n        }\n    }\n\n    func perform(_ job: StudioJob) async throws {\n        switch job {\n        case .examples:\n            guard let area = options.workArea else {\n                post(.examples([]))\n                return\n            }\n            post(.examples(Examples.load(area: area, attached: shared.attached)))\n        case .verify(let url):\n            try verify(url)\n        case .sessions:\n            guard let area = options.workArea else { throw BraidFailure.unavailable(\"no work area: nowhere to read sessions from\") }\n            post(.sessions(try Sessions.list(in: area.sessions)))\n        case .openSession(let url):\n            try await SessionReplayer.replay(url, delay: .milliseconds(25), post: post)\n        case .aii:\n            post(.aii(await AIIProbe.status(demoRoot: options.demoRoot)))\n        case .doctor:\n            let area: Result<WorkArea, Error> = options.workArea.map { .success($0) }\n                ?? .failure(BraidFailure.configuration(options.workAreaProblem ?? \"no work area: the T9 is not mounted\", hint: \"set BRAID_WORK_AREA or pass --work-area\"))\n            let checks = await DoctorChecks.run(area: area) { area in\n                guard FileManager.default.fileExists(atPath: area.configFile.path) else {\n                    throw BraidFailure.missing(\"no braid.toml in \\(area.root.path)\", hint: \"run braid init --base <pack or hf-id> first\")\n                }\n                return try BraidConfig.load(from: area.configFile)\n            }\n            post(.doctor(checks))\n        default:\n            break\n        }\n    }\n\n    /// Replays the log with no model: the arithmetic, the traces over each Thread's index layout,\n    /// every verbatim span re-read from the Thread's snapshot.\n    func verify(_ url: URL) throws {\n        guard let area = options.workArea else { throw BraidFailure.unavailable(\"no work area: the snapshots to verify against are there\") }\n        let session = try SessionReader.read(url)\n        let tokenizer = shared.tokenizerFolder.flatMap { try? BraidTokenizer(folder: $0) }\n        var snapshots: [CorpusSnapshot] = []\n        let names = Set(session.header.threads.filter { !$0.commons }.map(\\.name) + session.membership.filter { $0.kind == \"attach\" }.map(\\.thread.name))\n        for name in names.sorted() {\n            let layout = area.thread(name)\n            guard let live = try? ThreadStore.live(layout) else { continue }\n            if let snapshot = try? CorpusSnapshot.load(from: layout.snapshot(hash: live.snapshotHash)) { snapshots.append(snapshot) }\n        }\n        let layouts = shared.layouts\n        let report = Verifier.verify(session: session, name: url.lastPathComponent, layouts: { layouts[$0] },\n                                     reader: SnapshotPartitionReader(snapshots: snapshots), tokenizer: tokenizer)\n        post(.verified(report))\n    }\n}\n\nenum Sessions {\n    /// `*.jsonl` in a sessions directory, newest first (the names start with a timestamp).\n    static func list(in directory: URL) throws -> [URL] {\n        guard FileManager.default.fileExists(atPath: directory.path) else { return [] }\n        return try FileManager.default.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil)\n            .filter { $0.pathExtension == \"jsonl\" && !$0.lastPathComponent.hasPrefix(\"._\") }\n            .sorted { $0.lastPathComponent > $1.lastPathComponent }\n    }\n}\n\n/// Posts a saved session's lines in order, as the cluster posted them live.\nenum SessionReplayer {\n    static func replay(_ url: URL, delay: Duration, post: @Sendable (StudioEvent) -> Void, shouldStop: () -> Bool = { false }) async throws {\n        let session = try SessionReader.read(url)\n        post(.session(.header(session.header)))\n        for generation in session.generations {\n            let strands = SessionReplay.strands(for: generation, session: session)\n            post(.table(strands: strands, partitions: generation.end?.partitions ?? [], session: url))\n            post(.session(.gen(generation.gen)))\n            var membership = 0\n            for (k, step) in generation.steps.enumerated() {\n                while membership < generation.membership.count, generation.membership[membership].before == k {\n                    post(.session(.membership(generation.membership[membership].line)))\n                    membership += 1\n                }\n                if shouldStop() { throw CancellationError() }\n                post(.session(.step(step)))\n                if delay > .zero, !step.isPrompt { try await Task.sleep(for: delay) }\n            }\n            if let end = generation.end { post(.session(.end(end))) }\n        }\n    }\n}\n\n/// Fact prompts from the attached Threads' dataset nodes: the prompt and the answer the document holds.\nenum Examples {\n    static func load(area: WorkArea, attached: [String], perThread: Int = 40) -> [ExamplePrompt] {\n        let root = DatasetsRoot.resolve(workArea: area.root)\n        var examples: [ExamplePrompt] = []\n        for name in attached {\n            let layout = area.thread(name)\n            guard let info = try? ThreadStore.info(layout), let spec = try? CorpusSourceSpec(parsing: info.source),\n                  case .dataset(let nameOrPath, let node) = spec, let directory = try? DatasetsRoot.locate(nameOrPath, root: root) else { continue }\n            let factsURL = BraidDataset.nodeDirectory(directory, node).appendingPathComponent(\"facts.jsonl\")\n            guard let facts = try? JSONCoding.readLines(Fact.self, from: factsURL) else { continue }\n            // Only the facts of documents the Thread's snapshot holds (a --limit may have taken fewer).\n            var documents: Set<String>?\n            if let live = try? ThreadStore.live(layout), let snapshot = try? CorpusSnapshot.load(from: layout.snapshot(hash: live.snapshotHash)) {\n                documents = Set(snapshot.documents.map(\\.id))\n            }\n            var count = 0\n            for fact in facts where documents?.contains(fact.documentID) ?? true {\n                examples.append(ExamplePrompt(thread: name, label: \"\\(fact.kind) · \\(fact.subject)\", prompt: fact.prompt, expected: fact.answer))\n                count += 1\n                if count >= perThread { break }\n            }\n        }\n        return examples\n    }\n}\n\n/// The machine's AII and the demo AIIs, read-only: the home, its lanes, the Thread's health.\nenum AIIProbe {\n    static let lanes = [\"ambient\", \"craft\", \"veil\"]\n\n    static func status(demoRoot: URL, environment: [String: String] = ProcessInfo.processInfo.environment) async -> AIIStatus {\n        let machinePath = URL(fileURLWithPath: DoctorChecks.aiiHome(environment: environment), isDirectory: true)\n        let machine = await home(named: LaneAddress.machine, path: machinePath, demoRoot: demoRoot)\n        var demos: [AIIHomeStatus] = []\n        if let directories = try? FileManager.default.contentsOfDirectory(at: demoRoot, includingPropertiesForKeys: nil) {\n            for directory in directories.sorted(by: { $0.lastPathComponent < $1.lastPathComponent })\n            where FileManager.default.fileExists(atPath: directory.appendingPathComponent(\"layout.json\").path) {\n                demos.append(await home(named: directory.lastPathComponent, path: directory, demoRoot: demoRoot))\n            }\n        }\n        return AIIStatus(machine: machine, demoRoot: demoRoot.path, demos: demos)\n    }\n\n    static func home(named name: String, path: URL, demoRoot: URL) async -> AIIHomeStatus {\n        let manager = FileManager.default\n        let layout = manager.fileExists(atPath: path.appendingPathComponent(\"layout.json\").path)\n        let secrets = path.appendingPathComponent(\"secrets\", isDirectory: true)\n        let present = lanes.filter { manager.fileExists(atPath: secrets.appendingPathComponent($0).path) }\n        let stack = manager.fileExists(atPath: secrets.appendingPathComponent(\"aii\").path)\n        var status = AIIHomeStatus(name: name, path: path.path, layout: layout, lanes: present, stackSecret: stack, httpPort: nil, grpcPort: nil, health: nil, healthProblem: nil)\n        guard layout, let address = LaneAddress(parsing: \"\\(name)/ambient\"), let endpoint = try? LaneHomes.endpoint(for: address, demoRoot: demoRoot) else {\n            status.healthProblem = layout ? \"no Thread ports in aii/config.json\" : \"no AII home\"\n            return status\n        }\n        status.httpPort = endpoint.httpPort\n        status.grpcPort = endpoint.grpcPort\n        do {\n            let (data, _) = try await URLSession.shared.data(for: URLRequest(url: endpoint.healthURL, timeoutInterval: 3))\n            let body = String(decoding: data, as: UTF8.self)\n            let object = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]\n            if (object?[\"status\"] as? String) == \"healthy\" || body.contains(\"\\\"healthy\\\"\") {\n                var parts = [\"healthy on \\(endpoint.httpPort)\"]\n                if let stack = object?[\"stack\"] as? String { parts.append(\"stack \\(stack)\") }\n                if let contract = object?[\"contract\"] { parts.append(\"contract \\(contract)\") }\n                status.health = parts.joined(separator: \" · \")\n            } else {\n                status.healthProblem = \"not healthy: \\(body.prefix(60))\"\n            }\n        } catch {\n            status.healthProblem = \"unreachable on \\(endpoint.httpPort): \\(error.localizedDescription)\"\n        }\n        return status\n    }\n}\n"},{"path":"Sources/BraidStudio/Fixtures.swift","lines":179,"bytes":7973,"header":{"lines":[1,16],"what":[8,9],"pin":[13,15],"in":[10,12],"out":null},"marks":[],"first":1677,"scopes":[["S","FixtureManifest",null,"public",22,22,[22,49],51,null,-1,0],["S","ThreadSpec",null,"public",23,23,[23,48],35,null,0,0],["i","init",["name","label","source","version"],"public",29,29,[29,83],34,null,1,0],["S","ExampleSpec",null,"public",37,37,[37,49],42,null,0,0],["i","init",["threads","examples"],"public",47,47,[47,78],50,null,0,0],["C","FixtureBackend",null,"public final",53,53,[53,70],179,null,-1,0],["i","init",["directory","post"],"public",63,63,[63,88],68,null,5,0],["i","init",["directory","mailbox"],"public convenience",70,70,[70,82],72,null,5,0],["v","sessionsDirectory",null,"public",74,74,[74,38],74,null,5,8],["f","sessionURLs",[],"public",76,76,[76,46],76,null,5,8],["f","recordedSession",[],"public",79,79,[79,48],84,[78,78],5,0],["f","submit",["_"],"public",86,86,[86,41],103,null,5,0],["f","shutdown",[],"public",105,105,[105,33],105,null,5,8],["f","perform",["_"],"public",107,107,[107,55],143,null,5,0],["f","replay",["_"],"",145,145,[145,41],147,null,5,0],["f","strandNames",["_"],"",149,149,[149,58],152,null,5,0],["f","threads",["_"],"",154,154,[154,61],160,null,5,0],["f","postThreads",[],"",162,162,[162,30],164,null,5,0],["f","verify",["_"],"",167,167,[167,35],178,[166,166],5,0]],"text":"//\n//  Fixtures.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A backend that answers every job from a recorded session instead of MLX, so the studio\n//        can be demonstrated and tested anywhere: `braid ui --fixtures <dir>`.\n//  IN:   <dir>/sessions/*.jsonl (session logs as the cluster wrote them), <dir>/threads/<name>/\n//        snapshot.json (the Threads' snapshots, for verify), and an optional <dir>/fixtures.json\n//        naming the Threads (label, source, version) and a few example prompts.\n//  PIN:  Asking replays the newest recorded session, whatever the prompt; attach and detach change\n//        the Threads pane and nothing else; verification is real (it needs no model: spans are\n//        re-read from the snapshots by text hash).\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\npublic struct FixtureManifest: Codable, Sendable {\n    public struct ThreadSpec: Codable, Sendable {\n        public var name: String\n        public var label: String\n        public var source: String\n        public var version: String?\n\n        public init(name: String, label: String, source: String, version: String?) {\n            self.name = name\n            self.label = label\n            self.source = source\n            self.version = version\n        }\n    }\n\n    public struct ExampleSpec: Codable, Sendable {\n        public var thread: String\n        public var label: String\n        public var prompt: String\n        public var expected: String\n    }\n\n    public var threads: [ThreadSpec]?\n    public var examples: [ExampleSpec]?\n\n    public init(threads: [ThreadSpec]? = nil, examples: [ExampleSpec]? = nil) {\n        self.threads = threads\n        self.examples = examples\n    }\n}\n\npublic final class FixtureBackend: StudioBackend, @unchecked Sendable {\n    public let directory: URL\n    let manifest: FixtureManifest\n    let post: @Sendable (StudioEvent) -> Void\n    /// The pause between replayed tokens (tests set zero).\n    public var replayDelay: Duration = .milliseconds(40)\n    private let lock = NSLock()\n    private var detached: Set<String> = []\n    private var cancelled = false\n\n    public init(directory: URL, post: @escaping @Sendable (StudioEvent) -> Void) throws {\n        self.directory = directory\n        self.post = post\n        let manifestURL = directory.appendingPathComponent(\"fixtures.json\")\n        manifest = FileManager.default.fileExists(atPath: manifestURL.path) ? try JSONCoding.read(FixtureManifest.self, from: manifestURL) : FixtureManifest()\n    }\n\n    public convenience init(directory: URL, mailbox: Mailbox<StudioEvent>) throws {\n        try self.init(directory: directory, post: { mailbox.post($0) })\n    }\n\n    public var sessionsDirectory: URL { directory.appendingPathComponent(\"sessions\", isDirectory: true) }\n\n    public func sessionURLs() throws -> [URL] { try Sessions.list(in: sessionsDirectory) }\n\n    /// The newest recorded session: what an ask replays.\n    public func recordedSession() throws -> URL {\n        guard let url = try sessionURLs().first else {\n            throw BraidFailure.missing(\"the fixtures hold no session\", hint: \"copy a sessions/*.jsonl into \\(sessionsDirectory.path)\")\n        }\n        return url\n    }\n\n    public func submit(_ job: StudioJob) {\n        if case .cancel = job {\n            lock.withLock { cancelled = true }\n            return\n        }\n        guard let kind = job.kind else { return }\n        let post = self.post\n        Task.detached { [self] in\n            if kind == .generate || kind == .openSession { lock.withLock { cancelled = false } }\n            post(.jobStarted(kind, LiveBackend.label(job)))\n            do {\n                try await perform(job)\n                post(.jobFinished(kind))\n            } catch {\n                post(.jobFailed(kind, StudioFailure.describe(error)))\n            }\n        }\n    }\n\n    public func shutdown() async {}\n\n    public func perform(_ job: StudioJob) async throws {\n        switch job {\n        case .start:\n            let header = try SessionReader.read(try recordedSession()).header\n            post(.braid(BraidStatus(fixtures: true, workArea: directory.path, packName: header.pack.name, packSHA256: header.pack.sha256,\n                                    strands: strandNames(header), commons: header.threads.contains(where: \\.commons), sessionsDirectory: sessionsDirectory)))\n            post(.threads(threads(header)))\n        case .generate:\n            post(.log(\"fixture mode replays the recorded session; the prompt is not sent to a model\"))\n            try await replay(try recordedSession())\n        case .attach(let name):\n            lock.withLock { _ = detached.remove(name) }\n            post(.log(\"\\(name) attached (fixture mode: the recording is unchanged)\"))\n            try postThreads()\n        case .detach(let name):\n            lock.withLock { _ = detached.insert(name) }\n            post(.log(\"\\(name) detached (fixture mode: the recording is unchanged)\"))\n            try postThreads()\n        case .createThread:\n            throw BraidFailure.unavailable(\"fixture mode has no model to train a Thread\", hint: \"run braid ui without --fixtures\")\n        case .examples:\n            post(.examples((manifest.examples ?? []).map { ExamplePrompt(thread: $0.thread, label: $0.label, prompt: $0.prompt, expected: $0.expected) }))\n        case .verify(let url):\n            try verify(url)\n        case .sessions:\n            post(.sessions(try sessionURLs()))\n        case .openSession(let url):\n            try await replay(url)\n        case .aii:\n            post(.aii(await AIIProbe.status(demoRoot: StudioOptions.defaultDemoRoot())))\n        case .doctor:\n            let area: Result<WorkArea, Error> = .failure(BraidFailure.unavailable(\"fixture mode has no work area\", hint: \"run braid ui without --fixtures\"))\n            post(.doctor(await DoctorChecks.run(area: area) { _ in throw BraidFailure.unavailable(\"fixture mode\") }))\n        case .cancel:\n            break\n        }\n    }\n\n    func replay(_ url: URL) async throws {\n        try await SessionReplayer.replay(url, delay: replayDelay, post: post) { [self] in lock.withLock { cancelled } }\n    }\n\n    func strandNames(_ header: SessionHeader) -> [String] {\n        let detached = lock.withLock { self.detached }\n        return header.threads.map(\\.name).filter { !detached.contains($0) }\n    }\n\n    func threads(_ header: SessionHeader) -> [ThreadSummary] {\n        let detached = lock.withLock { self.detached }\n        let specs = manifest.threads ?? header.threads.filter { !$0.commons }.map {\n            FixtureManifest.ThreadSpec(name: $0.name, label: $0.label, source: \"recording\", version: $0.indexSHA256.map { \"index \" + String($0.prefix(12)) })\n        }\n        return specs.map { ThreadSummary(name: $0.name, label: $0.label, source: $0.source, version: $0.version, attached: !detached.contains($0.name)) }\n    }\n\n    func postThreads() throws {\n        post(.threads(threads(try SessionReader.read(try recordedSession()).header)))\n    }\n\n    /// Verification with no model: the arithmetic and every span re-read from the fixture's snapshots by text hash.\n    func verify(_ url: URL) throws {\n        let session = try SessionReader.read(url)\n        let threadsRoot = directory.appendingPathComponent(\"threads\", isDirectory: true)\n        var snapshots: [CorpusSnapshot] = []\n        if let folders = try? FileManager.default.contentsOfDirectory(at: threadsRoot, includingPropertiesForKeys: nil) {\n            for folder in folders.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {\n                if let snapshot = try? CorpusSnapshot.load(from: folder) { snapshots.append(snapshot) }\n            }\n        }\n        let report = Verifier.verify(session: session, name: url.lastPathComponent, layouts: { _ in nil }, reader: SnapshotPartitionReader(snapshots: snapshots), tokenizer: nil)\n        post(.verified(report))\n    }\n}\n"},{"path":"Sources/BraidStudio/MLXWorker.swift","lines":371,"bytes":18173,"header":{"lines":[1,19],"what":[8,13],"pin":[14,18],"in":null,"out":null},"marks":[[212,"Start"],[293,"Generate"],[354,"New Thread"]],"first":1696,"scopes":[["E","MembershipRequest",null,"",25,25,[25,33],29,null,-1,0,["attach","detach","cancel"]],["C","MLXWorker",null,"final",31,31,[31,43],371,null,-1,0],["i","init",["options","shared","post"],"",56,56,[56,103],65,null,1,0],["f","enqueue",["_"],"",67,67,[67,35],72,null,1,0],["f","request",["_"],"",75,75,[75,47],80,[74,74],1,0],["f","stop",[],"",82,82,[82,16],88,null,1,0],["f","loop",[],"private",90,90,[90,24],112,null,1,0],["f","drain",["generating"],"private",115,115,[115,41],121,[114,114],1,0],["f","apply",["_","generating"],"private",123,123,[123,73],158,null,1,0],["f","clusterEvent",["_"],"private",162,162,[162,53],184,[160,161],1,0],["S","MembershipFields",null,"private",187,187,[187,47],195,[186,186],1,0],["f","membershipLine",["kind","strand","thread","position","caughtUp","seconds"],"static",197,197,[197,147],201,null,1,0],["f","run",["_"],"private",203,203,[203,46],210,null,1,0],["f","start",[],"private",214,214,[214,32],260,null,1,0],["f","status",[],"private",262,262,[262,41],266,null,1,0],["f","postThreads",[],"private",268,268,[268,31],280,null,1,0],["f","loadNode",["_"],"private",283,283,[283,62],291,[282,282],1,0],["f","generate",["_"],"private",295,295,[295,61],352,null,1,0],["f","createThread",["_"],"private",356,356,[356,66],370,null,1,0]],"text":"//\n//  MLXWorker.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The one thread that runs MLX for the studio: loading the pack, the commons (whose tail\n//        every Thread runs behind its own head) and the Threads braid.toml attaches; generation;\n//        attaching a Thread (loading it first) and detaching one; creating a Thread. One job at a\n//        time, in order. Attach, detach and cancel requests are taken at token boundaries while a\n//        generation runs, so a Thread joins (and catches up on the session so far) or leaves\n//        mid-answer, as the cluster applies them.\n//  PIN:  A Foundation Thread with a 64 MB stack, never the cooperative pool — a generation blocks\n//        for seconds and training for minutes. The pack, the nodes and the cluster live here and\n//        never cross to the UI; only Sendable values do. One session log per answer: its header\n//        names the strands attached at the ask, and the attach/detach lines inside it mark where a\n//        strand joined or left.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\nenum MembershipRequest: Sendable {\n    case attach(String)\n    case detach(String)\n    case cancel\n}\n\nfinal class MLXWorker: @unchecked Sendable {\n    private let options: StudioOptions\n    private let shared: SharedBraid\n    private let post: @Sendable (StudioEvent) -> Void\n    private let condition = NSCondition()\n    private var queue: [StudioJob] = []\n    private var requests: [MembershipRequest] = []\n    private var stopping = false\n\n    // Touched only on the worker thread.\n    private var area: WorkArea?\n    private var config: BraidConfig?\n    private var pack: Pack?\n    private var tokenizer: BraidTokenizer?\n    private var cluster: Cluster?\n    private var nodes: [String: LocalNode] = [:]\n    /// The commons node and the reed, for the question path's stem rewrite.\n    private var commonsNode: LocalNode?\n    private var reed: MLXReed?\n    private var loadFailures: [String: String] = [:]\n    /// Inside `cluster.generate`: membership changes are logged lines then, and posted as such.\n    private var generating = false\n    /// The strands as they stood before the last membership change (a detach names an index into them).\n    private var lastStrands: [SessionThread] = []\n\n    init(options: StudioOptions, shared: SharedBraid, post: @escaping @Sendable (StudioEvent) -> Void) {\n        self.options = options\n        self.shared = shared\n        self.post = post\n        let thread = Thread { [weak self] in self?.loop() }\n        thread.name = \"braid.studio.mlx\"\n        thread.stackSize = 64 << 20\n        thread.qualityOfService = .userInitiated\n        thread.start()\n    }\n\n    func enqueue(_ job: StudioJob) {\n        condition.lock()\n        queue.append(job)\n        condition.signal()\n        condition.unlock()\n    }\n\n    /// Attach, detach or cancel: applied now when the worker is idle, at the next token boundary otherwise.\n    func request(_ request: MembershipRequest) {\n        condition.lock()\n        requests.append(request)\n        condition.signal()\n        condition.unlock()\n    }\n\n    func stop() {\n        condition.lock()\n        stopping = true\n        queue.removeAll()\n        condition.signal()\n        condition.unlock()\n    }\n\n    private func loop() {\n        while true {\n            condition.lock()\n            while queue.isEmpty, requests.isEmpty, !stopping { condition.wait() }\n            if stopping {\n                condition.unlock()\n                return\n            }\n            let pending = requests\n            requests.removeAll()\n            let job = queue.isEmpty ? nil : queue.removeFirst()\n            condition.unlock()\n            if !pending.isEmpty { apply(pending, generating: false) }\n            guard let job, let kind = job.kind else { continue }\n            post(.jobStarted(kind, LiveBackend.label(job)))\n            do {\n                try autoreleasepool { try run(job) }\n                post(.jobFinished(kind))\n            } catch {\n                post(.jobFailed(kind, StudioFailure.describe(error)))\n            }\n        }\n    }\n\n    /// Takes the membership requests that arrived; the cluster queues them while it generates.\n    private func drain(generating: Bool) {\n        condition.lock()\n        let pending = requests\n        requests.removeAll()\n        condition.unlock()\n        if !pending.isEmpty { apply(pending, generating: generating) }\n    }\n\n    private func apply(_ pending: [MembershipRequest], generating: Bool) {\n        for request in pending {\n            switch request {\n            case .cancel:\n                guard generating, let cluster else { continue }\n                cluster.cancel()\n                post(.log(\"cancelling at the next token boundary\"))\n            case .attach(let name):\n                guard let cluster else {\n                    post(.jobFailed(.membership, BraidFailure.unavailable(\"the braid is not up\", hint: \"see the Events pane for why the start failed\")))\n                    continue\n                }\n                post(.jobStarted(.membership, \"attaching \\(name)\"))\n                do {\n                    let node = try loadNode(name)\n                    try cluster.attach(node)\n                    if generating { post(.log(\"\\(name) joins at the next token boundary, catching up on the session so far\")) }\n                    post(.jobFinished(.membership))\n                } catch {\n                    post(.jobFailed(.membership, StudioFailure.describe(error)))\n                    postThreads()\n                }\n            case .detach(let name):\n                guard let cluster else { continue }\n                post(.jobStarted(.membership, \"detaching \\(name)\"))\n                do {\n                    try cluster.detach(name)\n                    if generating { post(.log(\"\\(name) leaves at the next token boundary\")) }\n                    post(.jobFinished(.membership))\n                } catch {\n                    post(.jobFailed(.membership, StudioFailure.describe(error)))\n                    postThreads()\n                }\n            }\n        }\n    }\n\n    /// The cluster's own report of a strand joining or leaving (now, or at the boundary it chose).\n    /// Mid-generation the cluster logged an attach/detach line; the same line goes to the screen.\n    private func clusterEvent(_ event: ClusterEvent) {\n        switch event {\n        case .attached(let name, let position, let caughtUp, let seconds):\n            let records = cluster?.strandRecords ?? []\n            if generating, let thread = records.last, thread.name == name,\n               let line = Self.membershipLine(kind: \"attach\", strand: records.count - 1, thread: thread, position: position, caughtUp: caughtUp, seconds: seconds) {\n                post(.session(.membership(line)))\n            }\n            lastStrands = records\n            post(.log(position > 0 ? String(format: \"%@ attached at position %d: caught up %d tokens in %.1f s\", name, position, caughtUp, seconds) : \"\\(name) attached\"))\n            postThreads()\n        case .detached(let name, let position):\n            if generating, let index = lastStrands.firstIndex(where: { $0.name == name }),\n               let line = Self.membershipLine(kind: \"detach\", strand: index, thread: lastStrands[index], position: position, caughtUp: 0, seconds: 0) {\n                post(.session(.membership(line)))\n            }\n            lastStrands = cluster?.strandRecords ?? []\n            post(.log(position > 0 ? \"\\(name) detached at position \\(position)\" : \"\\(name) detached\"))\n            postThreads()\n        case .step:\n            break\n        }\n    }\n\n    /// The attach/detach line as the cluster logs it (built through its coding keys; the record type has no public initialiser).\n    private struct MembershipFields: Encodable {\n        var kind: String\n        var t: Int\n        var thread: SessionThread\n        var position: Int\n        var caughtUp: Int\n        var seconds: Double\n        var memory: [Float]\n    }\n\n    static func membershipLine(kind: String, strand: Int, thread: SessionThread, position: Int, caughtUp: Int, seconds: Double) -> MembershipLine? {\n        let fields = MembershipFields(kind: kind, t: strand, thread: thread, position: position, caughtUp: caughtUp, seconds: seconds, memory: [])\n        guard let data = try? JSONCoding.lineEncoder().encode(fields) else { return nil }\n        return try? JSONCoding.decoder().decode(MembershipLine.self, from: data)\n    }\n\n    private func run(_ job: StudioJob) throws {\n        switch job {\n        case .start: try start()\n        case .generate(let request): try generate(request)\n        case .createThread(let request): try createThread(request)\n        default: break\n        }\n    }\n\n    // MARK: - Start\n\n    private func start() throws {\n        guard let area = options.workArea else {\n            throw BraidFailure.configuration(options.workAreaProblem ?? \"no work area: the T9 is not mounted\",\n                                             hint: \"set BRAID_WORK_AREA or pass --work-area; braid ui --fixtures <dir> replays a recording with no work area\")\n        }\n        guard FileManager.default.fileExists(atPath: area.configFile.path) else {\n            throw BraidFailure.missing(\"no braid.toml in \\(area.root.path)\", hint: \"run braid init --base <pack or hf-id> first\")\n        }\n        let config = try BraidConfig.load(from: area.configFile)\n        guard let packRecord = config.pack else { throw BraidFailure.missing(\"braid.toml names no pack\", hint: \"run braid init --base <pack or hf-id>\") }\n        post(.jobProgress(.start, \"loading the pack \\(packRecord.name)\"))\n        guard let pack = try DoctorChecks.findPack(packRecord.sha256, in: area) else {\n            throw BraidFailure.missing(\"braid.toml names a pack that is not on disk (\\(packRecord.sha256.prefix(12)))\", hint: \"run braid import \\(packRecord.name)\")\n        }\n        let tokenizer = try BraidTokenizer(folder: pack.tokenizerFolder)\n        let reed = pack.reed(tokens: tokenizer.vocabSize)\n        var settings = ClusterSettings()\n        settings.gate = config.gate\n        settings.k = config.index.k\n        let cluster = Cluster(reed: reed, tokenizer: tokenizer, pack: pack.identity, settings: settings)\n        cluster.onEvent = { [weak self] event in self?.clusterEvent(event) }\n        let scheme = KeyScheme(parsing: packRecord.keyScheme) ?? .residual(afterBlocks: pack.config.tapAfterBlocks)\n        self.area = area\n        self.config = config\n        self.pack = pack\n        self.tokenizer = tokenizer\n        self.cluster = cluster\n        shared.tokenizerFolder = pack.tokenizerFolder\n        post(.jobProgress(.start, \"loading the commons\"))\n        let commons = try ThreadStore.commons(pack: pack, scheme: scheme)\n        commonsNode = commons\n        self.reed = reed\n        post(.jobProgress(.start, \"the commons' tail \\(commons.languageModule.seamSHA256.prefix(12)) serves every Thread\"))\n        try cluster.attach(commons)\n        for name in config.attach {\n            post(.jobProgress(.start, \"loading \\(name)\"))\n            do {\n                try cluster.attach(try loadNode(name))\n            } catch {\n                let failure = StudioFailure.describe(error)\n                loadFailures[name] = failure.message\n                post(.log(\"\\(name) did not attach: \\(failure.message)\"))\n            }\n        }\n        post(.braid(status()))\n        postThreads()\n    }\n\n    private func status() -> BraidStatus {\n        BraidStatus(fixtures: false, workArea: area?.root.path, packName: pack?.info.name, packSHA256: pack?.sha256,\n                    strands: cluster?.strandNames ?? [], commons: cluster?.commonsIndex != nil, sessionsDirectory: area?.sessions,\n                    seamSHA256: commonsNode?.languageModule.seamSHA256)\n    }\n\n    private func postThreads() {\n        guard let area else { return }\n        let attached = cluster?.strandRecords.filter { !$0.commons }.map(\\.name) ?? []\n        shared.attached = attached\n        let infos = (try? ThreadStore.list(in: area)) ?? []\n        let summaries = infos.map { info -> ThreadSummary in\n            let live = try? ThreadStore.live(area.thread(info.name))\n            let version = live.map { \"v\\($0.version) \\($0.trained ? \"trained\" : \"base\") · index \\($0.indexSHA256.prefix(12))\" } ?? \"no live version\"\n            return ThreadSummary(name: info.name, label: info.label, source: info.source, version: version, attached: attached.contains(info.name),\n                                 error: loadFailures[info.name])\n        }\n        post(.threads(summaries))\n    }\n\n    /// The Thread's live version as a node, loaded once and kept (a detached Thread re-attaches without reloading).\n    private func loadNode(_ name: String) throws -> LocalNode {\n        if let node = nodes[name] { return node }\n        guard let area, let pack, let config, let commonsNode else { throw BraidFailure.unavailable(\"the braid is not up\") }\n        let loaded = try ThreadStore.load(name, in: area, pack: pack, commons: commonsNode, tau: Float(config.index.tau))\n        nodes[name] = loaded.node\n        loadFailures[name] = nil\n        shared.setLayout(try loaded.node.layout(), for: name)\n        return loaded.node\n    }\n\n    // MARK: - Generate\n\n    private func generate(_ request: GenerateRequest) throws {\n        guard let cluster, let tokenizer, let area, let config else {\n            throw BraidFailure.unavailable(\"the braid is not up\", hint: \"see the Events pane for why the start failed\")\n        }\n        drain(generating: false)\n        guard !cluster.strandNames.isEmpty else { throw BraidFailure.unavailable(\"no strands attached\", hint: \"space attaches the focused Thread\") }\n        cluster.closeLog()\n        try FileManager.default.createDirectory(at: area.sessions, withIntermediateDirectories: true)\n        let url = area.sessions.appendingPathComponent(SessionLog.fileName(sessionID: cluster.sessionID))\n        try cluster.startLog(at: url)\n        var params = GenerationParameters()\n        params.lambda = request.lambda\n        params.temperature = request.temperature\n        params.maxTokens = request.maxTokens\n        params.tau = Float(config.index.tau)\n        params.k = config.index.k\n        // A question (Q/A on, a trailing \"?\") goes through the path `braid chat` and `bench question`\n        // use: the commons rewrites it into a stem, each attached Thread finds its own context, and the\n        // answer stops at the end of the sentence.\n        var prompt = GenerationPrompt(text: request.prompt, tokens: tokenizer.encode(request.prompt))\n        var contexts: [String: NodeContext] = [:]\n        if request.question, let commonsNode, let reed {\n            let attached = cluster.strandNames.compactMap { name in nodes[name].map { (name: name, node: $0) } }\n            let turn = try QuestionPath.prepare(question: request.prompt, adapter: QuestionAdapter(languageModule: commonsNode.languageModule, reed: reed, tokenizer: tokenizer),\n                                                nodes: attached, tokenizer: tokenizer, k: config.index.k, rewriteTokens: request.maxTokens)\n            prompt = turn.prompt\n            contexts = turn.contexts\n            params = QuestionPath.parameters(params)\n            post(.log(\"question ▸ \\(turn.stem.debugDescription) (\\(turn.rewrite?.rewriter ?? \"as written\"))\"))\n            for name in attached.map(\\.name) {\n                if let found = turn.contexts[name] {\n                    post(.log(\"  \\(name): context \\(tokenizer.decode(found.tokens).debugDescription) (cos \\(String(format: \"%.2f\", found.score)))\"))\n                } else {\n                    post(.log(\"  \\(name): no context; it completes the bare stem\"))\n                }\n            }\n        }\n        let strands = cluster.strandRecords\n        let header = SessionHeader(sessionID: cluster.sessionID, pack: cluster.pack, gate: cluster.settings.gate, trace: cluster.settings.trace,\n                                   module: cluster.settings.module, hitsLogged: cluster.settings.hitsLogged, threads: strands)\n        let generationID = SessionLog.generationID(pack: cluster.pack, threads: strands, gateFingerprint: cluster.settings.gate.fingerprint, prompt: prompt, params: params)\n        post(.table(strands: strands, partitions: Array(cluster.partitions.values), session: url))\n        post(.session(.header(header)))\n        let contextRefs = cluster.contextRefs(contexts)\n        post(.session(.gen(GenerationLine(generationID: generationID, prompt: prompt, context: contextRefs.isEmpty ? nil : contextRefs, params: params,\n                                          strands: cluster.strandNames))))\n        let post = self.post\n        generating = true\n        lastStrands = strands\n        defer { generating = false }\n        let generation = try cluster.generate(prompt: prompt, contexts: contexts, params: params) { [weak self] step in\n            post(.session(.step(step)))\n            self?.drain(generating: true)\n        }\n        cluster.closeLog()\n        post(.session(.end(generation.end)))\n        post(.log(\"\\(generation.generated.count) tokens · \\(url.lastPathComponent)\"))\n    }\n\n    // MARK: - New Thread\n\n    private func createThread(_ request: NewThreadRequest) throws {\n        guard let area, let pack, let config else { throw BraidFailure.unavailable(\"the braid is not up\", hint: \"see the Events pane for why the start failed\") }\n        let recipe = try ThreadRecipe(request.name, corpus: request.corpus)\n        let post = self.post\n        let engine = BraidEngine(area: area, config: config, pack: pack, tokenizer: tokenizer, reed: reed, commons: commonsNode) { event in\n            guard let note = event.line else { return }\n            post(.jobProgress(.createThread, note))\n            post(.log(note))\n        }\n        let outcome = try engine.create(recipe)\n        self.config = engine.config\n        post(.log(outcome.summary))\n        if let cluster { try cluster.attach(try loadNode(request.name)) }\n        postThreads()\n    }\n}\n"},{"path":"Sources/BraidStudio/Screens/AIIScreen.swift","lines":79,"bytes":3875,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1715,"scopes":[["E","AIIScreen",null,"",17,17,[17,29],79,null,-1,0,[]],["f","render",["_","_","_"],"static",18,18,[18,81],43,null,0,0],["f","lines",["for","palette","glyphs"],"static",45,45,[45,91],66,null,0,0],["f","mark",["_"],"",46,46,[46,38],46,null,2,12],["f","handle",["_","_"],"static",68,68,[68,84],76,null,0,0],["f","hints",["_"],"static",78,78,[78,57],78,null,0,8]],"text":"//\n//  AIIScreen.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: 2 AII, read-only: the machine's Ambient Intelligence Index home (~/.rao, or AII_HOME) —\n//        layout.json, the lanes with a secret, the Thread's health on its HTTP port — and the demo\n//        AII homes under <repo>/aii, each the same way.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\nenum AIIScreen: StudioScreen {\n    static func render(_ state: StudioState, _ frame: inout Frame, _ rect: Rect) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        guard let status = state.aii.status else {\n            let inner = Theme.panel(\"Machine AII\", &frame, rect)\n            Theme.empty(state.status.jobs[.aii] != nil ? \"\\(StudioApp.spinner(state, glyphs)) detecting the AII…\" : \"r detects the machine's AII\", &frame, inner)\n            return\n        }\n        let machineHeight = min(rect.height, 9)\n        let (machineRect, demosRect) = rect.top(machineHeight)\n        let inner = Theme.panel(\"Machine AII · \\(Theme.abbreviate(status.machine.path))\", focused: true, &frame, machineRect)\n        Theme.rows(lines(for: status.machine, palette: palette, glyphs: glyphs), &frame, inner)\n        guard demosRect.height >= 3 else { return }\n        let demos = Theme.panel(\"Demo AIIs · \\(Theme.abbreviate(status.demoRoot))\", &frame, demosRect)\n        if status.demos.isEmpty {\n            Theme.empty(\"none · braid aii create <name> provisions one under \\(Theme.abbreviate(status.demoRoot)) (two demos ⇒ two Threads to attach and detach)\", &frame, demos)\n            return\n        }\n        var rows: [Text] = []\n        for demo in status.demos {\n            rows.append(Text(demo.name, style: palette.title) + Text(\"  \" + Theme.abbreviate(demo.path), style: palette.dim))\n            rows += lines(for: demo, palette: palette, glyphs: glyphs).map { Text(\"  \") + $0 }\n            rows.append(Text(\"\"))\n        }\n        Theme.rows(rows, &frame, demos)\n    }\n\n    static func lines(for home: AIIHomeStatus, palette: Palette, glyphs: Glyphs) -> [Text] {\n        func mark(_ ok: Bool) -> Text { Text(ok ? glyphs.check : glyphs.cross, style: ok ? palette.green : palette.red) }\n        var lines: [Text] = []\n        lines.append(mark(home.layout) + Text(\" layout.json \", style: palette.text) + Text(home.layout ? \"present\" : \"missing\", style: palette.dim))\n        var lanes = mark(!home.lanes.isEmpty) + Text(\" lanes       \", style: palette.text)\n        for lane in [\"ambient\", \"craft\", \"veil\"] {\n            let has = home.lanes.contains(lane)\n            lanes.append(lane + \" \", has ? palette.text : palette.muted)\n            lanes.append((has ? glyphs.live : glyphs.idle) + \"  \", has ? palette.green : palette.muted)\n        }\n        lanes.append(\"stack secret \" + (home.stackSecret ? glyphs.live : glyphs.idle), palette.dim)\n        lines.append(lanes)\n        var thread = Text(\"\", style: palette.text)\n        if let health = home.health {\n            thread = mark(true) + Text(\" Thread      \", style: palette.text) + Text(health, style: palette.green)\n        } else {\n            thread = mark(false) + Text(\" Thread      \", style: palette.text) + Text(home.healthProblem ?? \"unreachable\", style: palette.orange)\n        }\n        if let http = home.httpPort, let grpc = home.grpcPort { thread.append(\"  · http \\(http) · grpc \\(grpc)\", palette.dim) }\n        lines.append(thread)\n        return lines\n    }\n\n    static func handle(_ key: KeyEvent, _ state: inout StudioState) -> [StudioJob]? {\n        switch key.key {\n        case .char(\"r\"):\n            guard state.status.jobs[.aii] == nil else { return [] }\n            return [.aii]\n        default:\n            return nil\n        }\n    }\n\n    static func hints(_ state: StudioState) -> [KeyHint] { [KeyHint(\"r\", \"refresh\")] }\n}\n"},{"path":"Sources/BraidStudio/Screens/BraidArt.swift","lines":37,"bytes":1453,"header":{"lines":[1,12],"what":[8,10],"pin":[11,11],"in":null,"out":null},"marks":[],"first":1721,"scopes":[["E","BraidArt",null,"",18,18,[18,14],37,null,-1,0,[]],["f","strandColor",["_","_"],"static",21,21,[21,71],23,null,0,0],["f","tokenStyle",["step","uncited","commons","colour","palette"],"static",26,26,[26,120],36,[25,25],0,0]],"text":"//\n//  BraidArt.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The braid screen's colours: each Thread's strand colour, and a token's from the strand\n//        that supplied it — gold where the commons did, the off-white line where no strand reached\n//        0.6 of it, dim where no retrieved context predicted it.\n//  PIN:  A function of the state alone, so a frame can be tested as text.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\nenum BraidArt {\n    static let dominance: Float = 0.6\n\n    static func strandColor(_ index: Int, _ palette: Palette) -> Color {\n        palette.braid.isEmpty ? .default : palette.braid[index % palette.braid.count]\n    }\n\n    /// A generated token's style: its dominant strand's colour, the commons' gold, or \"shared\".\n    static func tokenStyle(step: Step, uncited: Bool, commons: Int?, colour: (Int) -> Color, palette: Palette) -> Style {\n        guard let records = step.threads, !records.isEmpty else { return palette.text }\n        var style: Style\n        if let dominant = step.dominant(threshold: dominance) {\n            style = Style(foreground: dominant == commons ? palette.goldColor : colour(dominant), background: palette.base.background)\n        } else {\n            style = Style(foreground: palette.line, background: palette.base.background)\n        }\n        if uncited { style = style.dim() }\n        return style\n    }\n}\n"},{"path":"Sources/BraidStudio/Screens/BraidScreen.swift","lines":474,"bytes":28428,"header":{"lines":[1,16],"what":[8,13],"pin":[14,15],"in":null,"out":null},"marks":[[23,"Examples"],[34,"Keys"],[165,"Colours"],[184,"Render"],[201,"The braid: the strip and the detail block"],[309,"The Threads pane"],[375,"The Royalties pane"],[416,"The prompt and the events"]],"first":1724,"scopes":[["E","BraidScreen",null,"",22,22,[22,31],474,null,-1,0,[]],["f","choose",["example","state"],"static",25,25,[25,69],32,null,0,0],["f","handle",["_","_"],"static",36,36,[36,84],115,null,0,0],["f","ask",["_"],"static",117,117,[117,63],135,null,0,0],["f","toggleMembership",["_"],"static",137,137,[137,76],152,null,0,0],["f","hints",["_"],"static",154,154,[154,57],163,null,0,0],["f","threadColor",["_","_","_"],"static",168,168,[168,96],170,[167,167],0,0],["f","colour",["_","view","state","palette"],"static",173,173,[173,107],180,[172,172],0,0],["f","display",["_","_"],"static",182,182,[182,68],182,null,0,8],["f","render",["_","_","_"],"static",186,186,[186,81],199,null,0,0],["f","renderBraid",["_","_","_","compact"],"static",203,203,[203,101],241,null,0,0],["f","renderStrip",["_","_","_"],"static",243,243,[243,86],307,null,0,0],["f","shareCell",["_","view","colour","palette","glyphs","width"],"static",311,311,[311,134],318,null,0,0],["f","renderThreads",["_","_","_"],"static",320,320,[320,88],373,null,0,0],["f","renderRoyalties",["_","_","_"],"static",377,377,[377,90],414,null,0,0],["f","name",["_"],"",387,387,[387,44],392,null,14,4],["f","tint",["_"],"",393,393,[393,45],393,null,14,12],["f","renderBottom",["_","_","_"],"static",418,418,[418,87],473,null,0,0]],"text":"//\n//  BraidScreen.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: 1 Braid, the main screen: the answer strip (the prompt dim, ▸, every generated token\n//        coloured by the strand that supplied it), the detail block for the token under the cursor\n//        (who supplied it and every share, its trace and both entropies with their deltas, the\n//        shadow β4 share, its citation and verification), the Threads pane (attached or detached,\n//        live share bars, Σ share), the Royalties pane (shares or credit, per strand and per cited\n//        document), the prompt line and the Events pane.\n//  PIN:  Everything drawn comes from the session's log lines and the views derived from them; a\n//        replayed session looks exactly like the live one did.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\nenum BraidScreen: StudioScreen {\n    // MARK: - Examples\n\n    static func choose(example index: Int, state: inout StudioState) {\n        let examples = state.braid.examples\n        guard !examples.isEmpty else { return }\n        let i = (index % examples.count + examples.count) % examples.count\n        state.braid.exampleIndex = i\n        state.braid.prompt.set(examples[i].prompt)\n        state.status.message = \"example \\(i + 1)/\\(examples.count) · \\(examples[i].thread) · \\(examples[i].label) · expects \\(examples[i].expected.trimmingCharacters(in: .whitespaces))\"\n    }\n\n    // MARK: - Keys\n\n    static func handle(_ key: KeyEvent, _ state: inout StudioState) -> [StudioJob]? {\n        if state.braid.editingPrompt {\n            switch key.key {\n            case .escape:\n                state.braid.editingPrompt = false\n            case .enter:\n                state.braid.editingPrompt = false\n                return ask(&state)\n            default:\n                if state.braid.prompt.handle(key) { state.braid.exampleIndex = -1 }\n            }\n            return []\n        }\n        switch key.key {\n        case .char(\"/\"), .char(\"p\"):\n            state.braid.editingPrompt = true\n        case .enter:\n            return ask(&state)\n        case .tab, .backTab:\n            let count = state.braid.threads.count\n            guard count > 0 else { return [] }\n            state.braid.focus = (state.braid.focus + (key.key == .tab ? 1 : count - 1)) % count\n        case .char(\" \"):\n            return toggleMembership(&state)\n        case .char(\"n\"):\n            state.overlay = .newThread(NewThreadForm())\n        case .char(\"R\"):\n            state.braid.royalties = state.braid.royalties == .shares ? .credit : .shares\n            state.status.message = state.braid.royalties == .shares\n                ? \"royalties by share: the tokens each strand led and its summed share\"\n                : \"royalties by credit: form tokens are the commons', content tokens each strand's, weighted by bits; then per cited document\"\n        case .left, .char(\"h\"):\n            state.braid.cursor = max(0, state.braid.cursor - 1)\n        case .right, .char(\"l\"):\n            state.braid.cursor = min(max(0, (state.braid.current?.walkable.count ?? 1) - 1), state.braid.cursor + 1)\n        case .home:\n            state.braid.cursor = 0\n        case .end:\n            state.braid.cursor = max(0, (state.braid.current?.walkable.count ?? 1) - 1)\n        case .char(\"v\"):\n            guard let url = state.braid.sessionURL, state.braid.current?.isComplete == true, !state.braid.generating else {\n                state.status.message = state.braid.current == nil ? \"nothing to verify yet: ⏎ asks the braid\" : \"wait for the answer to finish\"\n                return []\n            }\n            return [.verify(url)]\n        case .char(\"o\"):\n            return [.sessions]\n        case .char(\"x\"):\n            guard !state.braid.examples.isEmpty else {\n                state.status.message = \"no example prompts: a Thread from a dataset node (dataset:<name>#<node>) carries facts\"\n                return []\n            }\n            choose(example: state.braid.exampleIndex + 1, state: &state)\n        case .char(\"r\"):\n            state.braid.questions.toggle()\n            state.status.message = state.braid.questions\n                ? \"Q/A on: a prompt ending in \\\"?\\\" is rewritten into a stem (the flag is recorded; the stem adapter arrives with the question step)\"\n                : \"Q/A off: every prompt is completed as written, a question too\"\n        case .char(\"t\"):\n            state.braid.temperature = state.braid.temperature > 0 ? 0 : 0.8\n            state.status.message = state.braid.temperature > 0\n                ? \"sampling: each token is drawn from the mixture, so every strand gets chosen in proportion\"\n                : \"the likeliest token each time\"\n        case .char(\"-\"), .char(\"_\"):\n            state.braid.lambda = max(0, (state.braid.lambda * 20 - 1).rounded() / 20)\n            state.status.message = String(format: \"λ %.2f: the next answer leans %@ on retrieval\", state.braid.lambda, state.braid.lambda < 0.5 ? \"less\" : \"more\")\n        case .char(\"+\"), .char(\"=\"):\n            state.braid.lambda = min(1, (state.braid.lambda * 20 + 1).rounded() / 20)\n            state.status.message = String(format: \"λ %.2f: the next answer leans %@ on retrieval\", state.braid.lambda, state.braid.lambda < 0.5 ? \"less\" : \"more\")\n        case .char(\"c\"):\n            guard state.braid.generating || state.status.mlxJob != nil else {\n                state.status.message = \"nothing is running\"\n                return []\n            }\n            return [.cancel]\n        default:\n            return nil\n        }\n        return []\n    }\n\n    static func ask(_ state: inout StudioState) -> [StudioJob] {\n        guard state.braid.ready || state.fixtures else {\n            state.status.error = BraidFailure.unavailable(\"the braid is not up\", hint: state.braid.status == nil ? \"it is still loading, or the start failed (see the Events pane)\" : \"attach a Thread with space, or create one with n\")\n            return []\n        }\n        if let job = state.status.mlxJob {\n            state.status.error = BraidFailure.temporary(\"the MLX worker is busy: \\(job.label)\", hint: \"c cancels a generation\")\n            return []\n        }\n        let text = state.braid.prompt.text.trimmingCharacters(in: .whitespaces)\n        guard !text.isEmpty else {\n            state.status.error = BraidFailure.usage(\"the prompt is empty\", hint: \"/ types one, x takes a fact prompt\")\n            return []\n        }\n        let question = state.braid.questions && text.hasSuffix(\"?\")\n        state.braid.generating = true\n        state.status.message = \"asking \\(state.braid.status?.strands.count ?? 0) strands…\"\n        return [.generate(GenerateRequest(prompt: text, lambda: state.braid.lambda, temperature: state.braid.temperature, maxTokens: 24, question: question))]\n    }\n\n    static func toggleMembership(_ state: inout StudioState) -> [StudioJob] {\n        guard let thread = state.braid.focusedThread else {\n            state.status.message = \"no Threads in the work area: n creates one\"\n            return []\n        }\n        guard !state.braid.pending.contains(thread.name) else { return [] }\n        if let error = thread.error, !thread.attached {\n            state.status.error = BraidFailure.data(\"\\(thread.name) cannot attach: \\(error)\")\n            return []\n        }\n        state.braid.pending.insert(thread.name)\n        state.status.message = thread.attached\n            ? \"detaching \\(thread.name)\" + (state.braid.generating ? \" at the next token boundary\" : \"\")\n            : \"attaching \\(thread.name)\" + (state.braid.generating ? \" at the next token boundary (it catches up on the session so far)\" : \"\")\n        return [thread.attached ? .detach(thread.name) : .attach(thread.name)]\n    }\n\n    static func hints(_ state: StudioState) -> [KeyHint] {\n        if state.braid.editingPrompt { return [KeyHint(\"⏎\", \"ask\"), KeyHint(\"esc\", \"done\")] }\n        var hints = [KeyHint(\"⏎\", \"ask\"), KeyHint(\"/\", \"prompt\"), KeyHint(\"tab\", \"Thread\"), KeyHint(\"space\", \"attach/detach\"), KeyHint(\"n\", \"new Thread\"),\n                     KeyHint(\"R\", state.braid.royalties == .shares ? \"credit\" : \"shares\"), KeyHint(\"←→\", \"token\")]\n        if state.braid.current?.isComplete == true { hints.append(KeyHint(\"v\", \"verify\")) }\n        hints += [KeyHint(\"o\", \"open\"), KeyHint(\"x\", \"example\"), KeyHint(\"r\", state.braid.questions ? \"Q/A on\" : \"Q/A off\"),\n                  KeyHint(\"t\", state.braid.temperature > 0 ? \"sampled\" : \"likeliest\"), KeyHint(\"-+\", \"λ\")]\n        if state.braid.generating { hints.append(KeyHint(\"c\", \"cancel\")) }\n        return hints\n    }\n\n    // MARK: - Colours\n\n    /// A Thread's strand colour: its place in the Threads pane.\n    static func threadColor(_ name: String, _ state: StudioState, _ palette: Palette) -> Color? {\n        state.braid.threads.firstIndex { $0.name == name }.map { BraidArt.strandColor($0, palette) }\n    }\n\n    /// A strand's colour in the generation shown: gold for the commons, its Thread's otherwise.\n    static func colour(_ strand: Int, view: GenerationView, state: StudioState, palette: Palette) -> Color {\n        guard strand < view.strands.count else { return palette.line }\n        let record = view.strands[strand]\n        if record.commons { return palette.goldColor }\n        if let colour = threadColor(record.name, state, palette) { return colour }\n        let threads = view.strands.indices.filter { !view.strands[$0].commons }\n        return BraidArt.strandColor(threads.firstIndex(of: strand) ?? strand, palette)\n    }\n\n    static func display(_ text: String, _ glyphs: Glyphs) -> String { text.replacingOccurrences(of: \"\\n\", with: glyphs.newline) }\n\n    // MARK: - Render\n\n    static func render(_ state: StudioState, _ frame: inout Frame, _ rect: Rect) {\n        let compact = rect.height < 30\n        let (topRect, below) = rect.top(min(compact ? 7 : 9, rect.height))\n        renderBraid(state, &frame, topRect, compact: compact)\n        let hasCommons = state.braid.status?.commons ?? (state.braid.current?.commons != nil)\n        // The panes' tables: a border, a header and its rule, then one row per strand.\n        let rows = state.braid.threads.count + (hasCommons ? 1 : 0)\n        let middleHeight = min(max(0, below.height - 5), max(5, 4 + rows))\n        let (middleRect, bottomRect) = below.top(middleHeight)\n        let middle = middleRect.splitHorizontally([.flex(3), .flex(2)])\n        renderThreads(state, &frame, middle[0])\n        renderRoyalties(state, &frame, middle[1])\n        if bottomRect.height >= 3 { renderBottom(state, &frame, bottomRect) }\n    }\n\n    // MARK: The braid: the strip and the detail block\n\n    static func renderBraid(_ state: StudioState, _ frame: inout Frame, _ rect: Rect, compact: Bool) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        var title = \"Braid\"\n        if let status = state.braid.status {\n            title += \" · \\(status.packName ?? \"no pack\")\"\n        }\n        title += String(format: \" · λ %.2f · %@ · Q/A %@\", state.braid.lambda, state.braid.temperature > 0 ? \"sampled\" : \"likeliest\", state.braid.questions ? \"on\" : \"off\")\n        var footer: Text? = nil\n        if let url = state.braid.sessionURL {\n            footer = Text(\"session \" + url.deletingPathExtension().lastPathComponent, style: palette.dim)\n        } else if state.fixtures {\n            footer = Text(\"fixtures\", style: palette.orange)\n        }\n        let inner = Theme.panel(title, focused: !state.braid.editingPrompt, footer: footer, &frame, rect)\n        guard !inner.isEmpty else { return }\n        let stripHeight = min(compact ? 2 : 3, inner.height)\n        let strip = Rect(x: inner.minX, y: inner.minY, width: inner.width, height: stripHeight)\n        renderStrip(state, &frame, strip)\n        let detail = inner.inset(top: stripHeight, left: 0, bottom: 0, right: 0)\n        guard !detail.isEmpty else { return }\n        guard let view = state.braid.current, !view.walkable.isEmpty else {\n            if state.braid.generating {\n                Theme.rows([Text(\"\\(StudioApp.spinner(state, glyphs)) the braid is asking the strands…\", style: palette.orange)], &frame, detail)\n            } else if state.braid.status == nil {\n                Theme.empty(\"starting the braid: loading the pack, the commons and the Threads braid.toml attaches…\", &frame, detail)\n            } else if state.braid.ready {\n                Theme.empty(\"⏎ asks the braid · / types a prompt · x takes a fact prompt from a Thread · o replays a saved session · space attaches or detaches the focused Thread\", &frame, detail)\n            } else {\n                Theme.empty(\"no strands attached: space attaches the focused Thread, n creates one from a dataset node\", &frame, detail)\n            }\n            return\n        }\n        let cursor = min(state.braid.cursor, view.walkable.count - 1)\n        let k = view.walkable[cursor]\n        let styles = DetailStyles(text: palette.text, title: palette.title, dim: palette.dim, muted: palette.muted, gold: palette.gold, red: palette.red,\n                                  strand: { Style(foreground: colour($0, view: view, state: state, palette: palette), background: palette.base.background) })\n        Theme.rows(TokenDetail.styled(view, shared: k, styles: styles, glyphs: glyphs), &frame, detail)\n    }\n\n    static func renderStrip(_ state: StudioState, _ frame: inout Frame, _ rect: Rect) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        guard !rect.isEmpty else { return }\n        var pieces: [(String, Style)] = []\n        if let view = state.braid.current {\n            let shared = view.shared\n            let cursor = min(state.braid.cursor, max(0, view.walkable.count - 1))\n            var sawGenerated = false\n            for (w, k) in view.walkable.enumerated() {\n                let step = shared[k]\n                var style: Style\n                if step.isPrompt {\n                    style = palette.dim\n                } else {\n                    if !sawGenerated {\n                        pieces.append((\" \", palette.dim))\n                        pieces.append((glyphs.prompt, palette.gold))\n                        sawGenerated = true\n                    }\n                    let annotation = view.annotation(shared: k)\n                    style = BraidArt.tokenStyle(step: step, uncited: annotation?.uncited ?? true, commons: view.commons,\n                                                colour: { colour($0, view: view, state: state, palette: palette) }, palette: palette)\n                    if view.isVerified(spanIndex: annotation?.spanIndex) { style = style.underline() }\n                }\n                if w == cursor { style = style.reverse() }\n                pieces.append((display(step.text, glyphs), style))\n            }\n            if !sawGenerated, state.braid.generating {\n                pieces.append((\" \", palette.dim))\n                pieces.append((glyphs.prompt, palette.gold))\n            }\n            if state.braid.generating { pieces.append((\" \" + StudioApp.spinner(state, glyphs), palette.gold)) }\n        } else {\n            let text = state.braid.prompt.text.trimmingCharacters(in: .whitespacesAndNewlines)\n            if !text.isEmpty { pieces.append((text, palette.dim)) }\n            if state.braid.generating { pieces.append((\" \" + glyphs.prompt + \" \" + StudioApp.spinner(state, glyphs), palette.gold)) }\n        }\n        // Wrap, keeping the cursor's line in view; a token that fits on a line is not split across two.\n        var lines: [[(String, Style)]] = [[]]\n        var width = 0\n        var cursorLine = 0\n        for (text, style) in pieces {\n            let tokenWidth = TerminalWidth.of(text)\n            if style != palette.dim, tokenWidth <= rect.width, width + tokenWidth > rect.width {\n                lines.append([])\n                width = 0\n            }\n            for scalar in text.unicodeScalars {\n                let w = TerminalWidth.of(scalar)\n                if width + w > rect.width {\n                    lines.append([])\n                    width = 0\n                }\n                lines[lines.count - 1].append((String(Character(scalar)), style))\n                width += w\n            }\n            if style.attributes.contains(.reverse) { cursorLine = lines.count - 1 }\n        }\n        let first = max(0, min(max(cursorLine - rect.height + 1, lines.count - rect.height), lines.count - rect.height))\n        for (row, line) in lines.dropFirst(first).prefix(rect.height).enumerated() {\n            var x = rect.minX\n            for (piece, style) in line { x += frame.canvas.put(piece, x: x, y: rect.minY + row, style: style, clip: rect) }\n        }\n    }\n\n    // MARK: The Threads pane\n\n    static func shareCell(_ strand: Int?, view: GenerationView?, colour: Color, palette: Palette, glyphs: Glyphs, width: Int) -> Text {\n        guard let strand, let view, strand < view.strands.count, let royalties = view.royalties, royalties.generated > 0,\n              let line = royalties.strands.first(where: { $0.name == view.strands[strand].name }) else { return Text(\"—\", style: palette.muted) }\n        let mean = line.share / Double(royalties.generated)\n        var text = ShareBar(segments: [(mean, colour)], track: palette.muted, glyphs: glyphs).text(width: max(4, width - 8))\n        text.append(\" Σ \" + Theme.f(line.share), palette.text)\n        return text\n    }\n\n    static func renderThreads(_ state: StudioState, _ frame: inout Frame, _ rect: Rect) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        let inner = Theme.panel(\"Threads · tab focuses · space attaches/detaches · n new\", &frame, rect)\n        guard !inner.isEmpty else { return }\n        let view = state.braid.current\n        let hasCommons = state.braid.status?.commons ?? (view?.commons != nil)\n        let wide = inner.width >= 60\n        let shareWidth = 16\n        var rows: [[Text]] = []\n        if hasCommons {\n            rows.append([\n                Text(\"Commons\", style: Style(foreground: palette.goldColor, background: palette.base.background, attributes: .bold)),\n                Text((state.braid.status?.packName ?? \"the pack\") + (state.braid.status?.seamSHA256.map { \" · tail \\($0.prefix(12)), every Thread's\" } ?? \"\"), style: palette.dim),\n                Text(\"\\(glyphs.live) commons\", style: palette.gold),\n                shareCell(view?.commons, view: view, colour: palette.goldColor, palette: palette, glyphs: glyphs, width: shareWidth),\n            ])\n        }\n        for (index, thread) in state.braid.threads.enumerated() {\n            let colour = BraidArt.strandColor(index, palette)\n            let tint = Style(foreground: colour, background: palette.base.background)\n            let strand = view?.strands.firstIndex { $0.name == thread.name && !$0.commons }\n            let status: Text\n            if state.braid.pending.contains(thread.name) {\n                status = Text(\"\\(StudioApp.spinner(state, glyphs)) \\(thread.attached ? \"detaching\" : \"attaching\")\", style: palette.orange)\n            } else if let error = thread.error, !thread.attached {\n                status = Text(\"\\(glyphs.cross) \\(error)\", style: palette.red)\n            } else if thread.attached {\n                status = Text(\"\\(glyphs.live) attached\", style: tint)\n            } else {\n                status = Text(\"\\(glyphs.idle) detached\", style: palette.muted)\n            }\n            var source = thread.source\n            if source.hasPrefix(\"dataset:\") { source = String(source.dropFirst(8)) }\n            rows.append([\n                Text(thread.label, style: thread.attached ? tint.bold() : palette.muted),\n                Text(source + (thread.version.map { \" · \" + $0 } ?? \"\"), style: palette.dim),\n                status,\n                shareCell(strand, view: view, colour: colour, palette: palette, glyphs: glyphs, width: shareWidth),\n            ])\n        }\n        guard !rows.isEmpty else {\n            Theme.empty(state.braid.status == nil ? \"loading…\" : \"no Threads in the work area: n creates one from a dataset node\", &frame, inner)\n            return\n        }\n        // Narrow panes keep the Thread, its source and its state; the shares are in the Royalties pane.\n        let columns = wide\n            ? [Column(\"Thread\", .fixed(11)), Column(\"source\", .flex(1)), Column(\"state\", .fixed(11)), Column(\"share\", .fixed(shareWidth))]\n            : [Column(\"Thread\", .fixed(11)), Column(\"source\", .flex(1)), Column(\"state\", .fixed(11))]\n        if !wide { rows = rows.map { Array($0.prefix(3)) } }\n        var table = TableState(selected: state.braid.threads.isEmpty ? nil : state.braid.focus + (hasCommons ? 1 : 0))\n        table.clamp(rowCount: rows.count, visible: Table.visibleRows(in: inner, showHeader: true))\n        Table.styled(columns: columns, rows: rows, state: table, palette: palette, glyphs: glyphs).render(in: inner, on: &frame.canvas)\n    }\n\n    // MARK: The Royalties pane\n\n    static func renderRoyalties(_ state: StudioState, _ frame: inout Frame, _ rect: Rect) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        let shares = state.braid.royalties == .shares\n        let inner = Theme.panel(shares ? \"Royalties · shares (R: credit)\" : \"Royalties · credit (R: shares)\", &frame, rect)\n        guard !inner.isEmpty else { return }\n        guard let view = state.braid.current, let royalties = view.royalties, royalties.generated > 0 else {\n            Theme.empty(\"⏎ asks the braid; royalties are derived from the log as the tokens arrive\", &frame, inner)\n            return\n        }\n        func name(_ thread: String) -> Text {\n            // A Thread detached since keeps its line, muted.\n            guard let t = view.currentIndex(of: thread) else { return Text(thread, style: palette.muted) }\n            let strand = view.strands[t]\n            return Text(strand.commons ? \"commons\" : strand.name, style: Style(foreground: colour(t, view: view, state: state, palette: palette), background: palette.base.background))\n        }\n        func tint(_ thread: String) -> Color { view.currentIndex(of: thread).map { colour($0, view: view, state: state, palette: palette) } ?? palette.muted.foreground }\n        var rows: [[Text]] = []\n        let columns: [Column]\n        if shares {\n            columns = [Column(\"strand\", .fixed(11)), Column(\"led\", .fixed(6), align: .trailing), Column(\"Σ share\", .fixed(8), align: .trailing), Column(\"\", .flex(1))]\n            for line in royalties.strands {\n                let mean = line.share / Double(royalties.generated)\n                rows.append([name(line.name), Text(\"\\(line.led)/\\(royalties.generated)\", style: palette.text), Text(Theme.f(line.share), style: palette.text),\n                             ShareBar(segments: [(mean, tint(line.name))], track: palette.muted, glyphs: glyphs).text(width: max(4, inner.width - 31))])\n            }\n        } else {\n            columns = [Column(\"strand · document\", .flex(1)), Column(\"tokens\", .fixed(6), align: .trailing), Column(\"Σ share\", .fixed(8), align: .trailing), Column(\"credit·bits\", .fixed(11), align: .trailing)]\n            for line in royalties.strands {\n                rows.append([name(line.name), Text(\"\", style: palette.dim), Text(Theme.f(line.share), style: palette.dim), Text(Theme.f(line.credit, 1), style: palette.text)])\n            }\n            for document in royalties.documents.prefix(max(0, inner.height - 2 - rows.count)) {\n                rows.append([name(document.name) + Text(\"/…\" + document.documentID.suffix(12), style: palette.dim), Text(\"\\(document.tokens)\", style: palette.text),\n                             Text(Theme.f(document.share), style: palette.text), Text(\"\", style: palette.dim)])\n            }\n        }\n        Table.styled(columns: columns, rows: rows, state: nil, palette: palette, glyphs: glyphs).render(in: inner, on: &frame.canvas)\n    }\n\n    // MARK: The prompt and the events\n\n    static func renderBottom(_ state: StudioState, _ frame: inout Frame, _ rect: Rect) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        let columns = rect.splitHorizontally([.flex(3), .flex(2)])\n        let examples = state.braid.examples\n        let footer = Text(state.braid.example == nil ? \"typed\" : \"example \\(state.braid.exampleIndex + 1)/\\(examples.count)\", style: palette.dim)\n        let prompt = Theme.panel(\"Prompt\", focused: state.braid.editingPrompt, footer: footer, &frame, columns[0])\n        if !prompt.isEmpty {\n            frame.canvas.put(\"prompt \\(glyphs.prompt)\", x: prompt.minX, y: prompt.minY, style: palette.dim, clip: prompt)\n            let field = Rect(x: prompt.minX + 9, y: prompt.minY, width: max(0, prompt.width - 9), height: 1)\n            if state.braid.editingPrompt {\n                if let cursor = TextField(state: state.braid.prompt, placeholder: \"type the prompt · ⏎ asks · esc leaves\", focused: true,\n                                          style: palette.title, placeholderStyle: palette.muted, cursorStyle: palette.cursor).render(in: field, on: &frame.canvas) {\n                    frame.cursor = cursor\n                }\n            } else if state.braid.prompt.text.isEmpty {\n                frame.canvas.put(Text(\"/ types a prompt · x takes a fact prompt · ⏎ asks\", style: palette.muted).truncated(to: field.width), x: field.minX, y: field.minY, clip: field)\n            } else {\n                // Unfocused, the prompt reads from its start.\n                frame.canvas.put(Text(state.braid.prompt.text, style: palette.title).truncated(to: field.width), x: field.minX, y: field.minY, clip: field)\n            }\n            var lines: [Text] = []\n            if let example = state.braid.example {\n                var line = Text(\"\\(example.thread) · \\(example.label)\", style: palette.muted)\n                line.append(\"  expects\", palette.muted)\n                line.append(example.expected, palette.gold)\n                if let view = state.braid.current, view.isComplete, view.gen.prompt.text == example.prompt {\n                    let right = view.text.hasPrefix(example.expected)\n                    line.append(right ? \"  \\(glyphs.check) the answer matches\" : \"  \\(glyphs.cross) the answer differs\", right ? palette.green : palette.red)\n                }\n                lines.append(line)\n            }\n            lines.append(Text(String(format: \"λ %.2f · %@ · Q/A %@ · 24 tokens\", state.braid.lambda, state.braid.temperature > 0 ? \"sampled (t)\" : \"likeliest (t)\",\n                                     state.braid.questions ? \"on (r)\" : \"off (r)\"), style: palette.dim))\n            if let report = state.braid.verify {\n                let ok = report.status == .ok\n                lines.append(Text(\"\\(ok ? glyphs.verified : glyphs.cross) \\(report.spansVerified)/\\(report.spans.count) spans verified\"\n                                  + (report.issues.isEmpty ? \"\" : \" · \\(report.issues.count) replay issue\\(report.issues.count == 1 ? \"\" : \"s\")\"), style: ok ? palette.gold : palette.red))\n            } else if let view = state.braid.current, let end = view.end {\n                lines.append(Text(\"\\(end.generated) tokens · stopped on \\(end.stoppedOn?.rawValue ?? \"?\") · \\(view.spans.count) span\\(view.spans.count == 1 ? \"\" : \"s\") · v verifies\", style: palette.dim))\n            }\n            Theme.rows(lines, &frame, prompt.inset(top: 1, left: 0, bottom: 1, right: 0))\n            if prompt.height >= 3 {\n                var legend = Text(\"colour \", style: palette.muted)\n                for (index, thread) in state.braid.threads.enumerated() {\n                    legend.append(thread.label + \" \", Style(foreground: BraidArt.strandColor(index, palette), background: palette.base.background))\n                }\n                legend.append(\"commons \", palette.gold)\n                legend.append(\"shared \", Style(foreground: palette.line, background: palette.base.background))\n                legend.append(\"· dim = uncited · underline = verified span\", palette.muted)\n                frame.canvas.put(legend.truncated(to: prompt.width), x: prompt.minX, y: prompt.maxY - 1, clip: prompt)\n            }\n        }\n        let events = Theme.panel(\"Events\", &frame, columns[1])\n        LogPane(state: state.braid.events, style: palette.dim).render(in: events, on: &frame.canvas)\n    }\n}\n"},{"path":"Sources/BraidStudio/Screens/DoctorScreen.swift","lines":52,"bytes":2233,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":1742,"scopes":[["E","DoctorScreen",null,"",16,16,[16,32],52,null,-1,0,[]],["f","render",["_","_","_"],"static",17,17,[17,81],39,null,0,0],["f","handle",["_","_"],"static",41,41,[41,84],49,null,0,0],["f","hints",["_"],"static",51,51,[51,57],51,null,0,8]],"text":"//\n//  DoctorScreen.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: 3 Doctor: the checks `braid doctor` runs (BraidKit's DoctorChecks), with their verdicts\n//        and details; r runs them again.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\nenum DoctorScreen: StudioScreen {\n    static func render(_ state: StudioState, _ frame: inout Frame, _ rect: Rect) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        let checks = state.doctor.checks\n        let ok = checks.filter(\\.ok).count\n        let footer = checks.isEmpty ? nil : Text(\"\\(ok)/\\(checks.count) ok\", style: ok == checks.count ? palette.green : palette.orange)\n        let inner = Theme.panel(\"Doctor · the checks braid doctor runs\", focused: true, footer: footer, &frame, rect)\n        guard !inner.isEmpty else { return }\n        if checks.isEmpty {\n            Theme.empty(state.status.jobs[.doctor] != nil ? \"\\(StudioApp.spinner(state, glyphs)) running the checks…\" : \"r runs the checks\", &frame, inner)\n            return\n        }\n        var rows: [Text] = []\n        for check in checks {\n            var line = Text(check.ok ? glyphs.check : glyphs.cross, style: check.ok ? palette.green : palette.red)\n            line.append(\" \" + check.name.padding(toLength: 15, withPad: \" \", startingAt: 0), palette.text)\n            line.append(check.detail.replacingOccurrences(of: \"\\n\", with: \" \"), check.ok ? palette.dim : palette.orange)\n            rows.append(line)\n        }\n        rows.append(Text(\"\"))\n        rows.append(Text(ok == checks.count ? \"all checks passed\" : \"\\(checks.count - ok) check\\(checks.count - ok == 1 ? \"\" : \"s\") failed · braid doctor exits 1\", style: ok == checks.count ? palette.green : palette.orange))\n        Theme.rows(rows, &frame, inner)\n    }\n\n    static func handle(_ key: KeyEvent, _ state: inout StudioState) -> [StudioJob]? {\n        switch key.key {\n        case .char(\"r\"):\n            guard state.status.jobs[.doctor] == nil else { return [] }\n            return [.doctor]\n        default:\n            return nil\n        }\n    }\n\n    static func hints(_ state: StudioState) -> [KeyHint] { [KeyHint(\"r\", \"re-check\")] }\n}\n"},{"path":"Sources/BraidStudio/Screens/Theme.swift","lines":52,"bytes":2152,"header":{"lines":[1,10],"what":[8,9],"pin":null,"in":null,"out":null},"marks":[],"first":1746,"scopes":[["E","Theme",null,"",16,16,[16,11],52,null,-1,0,[]],["f","panel",["_","focused","footer","_","_"],"static",18,19,[19,127],23,[17,17],0,0],["f","empty",["_","_","_"],"static",25,25,[25,77],30,null,0,0],["f","rows",["_","_","_"],"static",33,33,[33,74],38,[32,32],0,0],["f","short",["_","_"],"static",40,40,[40,62],43,null,0,0],["f","f",["_","_"],"static",45,45,[45,59],45,null,0,8],["f","f",["_","_"],"static",46,46,[46,60],46,null,0,8],["f","abbreviate",["_"],"static",48,48,[48,53],51,null,0,0]],"text":"//\n//  Theme.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The few drawing helpers every screen uses: a titled panel that returns its content\n//        rectangle, a dim message for an empty panel, rows of styled text, short hashes.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\nenum Theme {\n    /// Draws a panel and returns its content rect (inset one cell on each side inside the border).\n    @discardableResult\n    static func panel(_ title: String, focused: Bool = false, footer: Text? = nil, _ frame: inout Frame, _ rect: Rect) -> Rect {\n        var box = Box.panel(title, focused: focused, palette: frame.palette, glyphs: frame.glyphs)\n        box.footer = footer\n        return box.render(in: rect, on: &frame.canvas).inset(top: 0, left: 1, bottom: 0, right: 1)\n    }\n\n    static func empty(_ message: String, _ frame: inout Frame, _ rect: Rect) {\n        guard !rect.isEmpty else { return }\n        for (row, line) in Paragraph.wrap(message, width: max(1, rect.width - 2)).prefix(rect.height).enumerated() {\n            frame.canvas.put(line, x: rect.minX + 1, y: rect.minY + row, style: frame.palette.dim, clip: rect)\n        }\n    }\n\n    /// Rows of text, each truncated to the rect, from its top.\n    static func rows(_ lines: [Text], _ frame: inout Frame, _ rect: Rect) {\n        guard !rect.isEmpty else { return }\n        for (row, line) in lines.prefix(rect.height).enumerated() {\n            frame.canvas.put(line.truncated(to: rect.width), x: rect.minX, y: rect.minY + row, clip: rect)\n        }\n    }\n\n    static func short(_ id: String?, _ n: Int = 12) -> String {\n        guard let id, !id.isEmpty else { return \"—\" }\n        return id.count > n ? String(id.prefix(n)) : id\n    }\n\n    static func f(_ x: Float, _ digits: Int = 2) -> String { String(format: \"%.\\(digits)f\", x) }\n    static func f(_ x: Double, _ digits: Int = 2) -> String { String(format: \"%.\\(digits)f\", x) }\n\n    static func abbreviate(_ path: String) -> String {\n        let home = NSHomeDirectory()\n        return path.hasPrefix(home) ? \"~\" + path.dropFirst(home.count) : path\n    }\n}\n"},{"path":"Sources/BraidStudio/SessionView.swift","lines":258,"bytes":13305,"header":{"lines":[1,15],"what":[8,12],"pin":[13,14],"in":null,"out":null},"marks":[],"first":1754,"scopes":[["S","GenerationView",null,"public",21,21,[21,39],134,null,-1,0],["i","init",["gen","strands","partitions"],"public",38,38,[38,91],42,null,0,0],["v","shared",null,"public",45,45,[45,30],45,[44,44],0,8],["v","walkable",null,"public",47,47,[47,31],47,[46,46],0,8],["v","generated",null,"public",48,48,[48,33],48,null,0,8],["v","commons",null,"public",49,49,[49,29],49,null,0,8],["v","text",null,"public",50,50,[50,28],50,null,0,8],["v","isComplete",null,"public",51,51,[51,32],51,null,0,8],["v","firstGenerated",null,"public",54,54,[54,35],57,[53,53],0,0],["f","append",["_"],"public mutating",59,59,[59,46],68,null,0,0],["v","sharedSlots",null,"public",71,71,[71,43],74,[70,70],0,0],["f","currentIndex",["of"],"public",77,77,[77,54],77,[76,76],0,8],["f","apply",["_"],"public mutating",80,80,[80,55],86,[79,79],0,0],["f","derive",[],"public mutating",89,89,[89,34],98,[88,88],0,0],["f","annotation",["shared"],"public",100,100,[100,61],100,null,0,8],["f","isVerified",["spanIndex"],"public",102,102,[102,52],105,null,0,0],["f","strand",["ofRow"],"public",108,108,[108,47],110,[107,107],0,0],["f","strandName",["ofRow"],"public",113,113,[113,54],116,[112,112],0,0],["f","previousRecord",["shared","strand"],"public",119,119,[119,78],133,[118,118],0,0],["S","DetailStyles",null,"public",137,137,[137,27],157,[136,136],-1,0],["i","init",["text","title","dim","muted","gold","red","strand"],"public",146,146,[146,128],154,null,19,0],["E","TokenDetail",null,"public",164,164,[164,24],258,[159,163],-1,0,[]],["f","f",["_","_"],"public static",167,167,[167,66],167,null,21,8],["f","plain",["_","shared","glyphs"],"public static",170,170,[170,107],172,[169,169],21,0],["f","styled",["_","shared","styles","glyphs"],"public static",177,177,[177,128],257,[174,176],21,0],["f","name",["_"],"",182,182,[182,38],182,null,24,12],["f","colour",["_"],"",185,185,[185,39],185,null,24,12]],"text":"//\n//  SessionView.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A generation as the screen holds it: the log lines that arrived (gen, tok…, end, any\n//        attach/detach between them), the strands and the partition table they are read against,\n//        and the views derived from them exactly as `braid verify` and `braid cluster spawn` derive\n//        them — citations and verbatim spans, credit, royalties. Also the per-token detail block\n//        (three lines) for the token under the cursor, as plain strings, so a test can pin them.\n//  PIN:  Nothing here is stored per token beyond the log line; everything else is recomputed from\n//        the lines, so a live session and a replayed one show the same numbers.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\npublic struct GenerationView: Sendable {\n    public var gen: GenerationLine\n    /// The strands in effect, in record order (attach and detach lines move them).\n    public var strands: [SessionThread]\n    /// The braid's global partition table, by row.\n    public var partitions: [Int: PartitionRef]\n    public var steps: [Step] = []\n    /// Per step (aligned with `steps`), the strands its records are in when it arrived.\n    public var stepSlots: [[StrandSlot]] = []\n    public var end: EndLine?\n    /// Per shared step (the context lines excluded), the citations and the span it belongs to.\n    public var annotations: [SpanAnnotation] = []\n    public var spans: [CitedSpan] = []\n    public var royalties: RoyaltiesView?\n    /// What `v` found, by span index.\n    public var verification: [Int: SpanCheck] = [:]\n\n    public init(gen: GenerationLine, strands: [SessionThread], partitions: [PartitionRef]) {\n        self.gen = gen\n        self.strands = strands\n        self.partitions = Dictionary(partitions.map { ($0.row, $0) }, uniquingKeysWith: { first, _ in first })\n    }\n\n    /// The steps the derived views run over: prompt and generated positions, context lines excluded.\n    public var shared: [Step] { steps.filter { $0.source != .ctx } }\n    /// Indices into `shared` the cursor walks: every position whose strands were asked (the eos opener has none).\n    public var walkable: [Int] { shared.indices.filter { shared[$0].threads != nil } }\n    public var generated: [Step] { steps.filter { !$0.isPrompt } }\n    public var commons: Int? { strands.firstIndex(where: \\.commons) }\n    public var text: String { end?.text ?? generated.map(\\.text).joined() }\n    public var isComplete: Bool { end != nil }\n\n    /// The cursor position of the first generated token (the prompt's positions come first).\n    public var firstGenerated: Int {\n        let shared = self.shared\n        return walkable.firstIndex { !shared[$0].isPrompt } ?? max(0, walkable.count - 1)\n    }\n\n    public mutating func append(_ step: Step) {\n        let current = strands.map(StrandSlot.init)\n        if step.source == .ctx, let owner = step.owner, current.indices.contains(owner) {\n            stepSlots.append([current[owner]])\n        } else {\n            stepSlots.append(current)\n        }\n        steps.append(step)\n        derive()\n    }\n\n    /// The slots of the shared steps (context lines excluded), aligned with `shared`.\n    public var sharedSlots: [[StrandSlot]] {\n        let current = strands.map(StrandSlot.init)\n        return steps.indices.filter { steps[$0].source != .ctx }.map { $0 < stepSlots.count ? stepSlots[$0] : current }\n    }\n\n    /// The current index of a Thread by name (for its colour), if it is still attached.\n    public func currentIndex(of name: String) -> Int? { strands.firstIndex { $0.name == name } }\n\n    /// An attach or detach line inside the generation: the strand list follows it.\n    public mutating func apply(_ line: MembershipLine) {\n        if line.kind == \"attach\" {\n            strands.append(line.thread)\n        } else if strands.indices.contains(line.strand) {\n            strands.remove(at: line.strand)\n        }\n    }\n\n    /// Recomputes citations, spans, credit and royalties from the lines so far.\n    public mutating func derive() {\n        let shared = self.shared\n        let slots = sharedSlots\n        let found = Spans.annotate(steps: shared, slots: slots, partitions: partitions)\n        annotations = found.annotations\n        spans = found.spans\n        var credits = Credit.assign(shared, slots: slots)\n        _ = FollowedCredit.apply(&credits, steps: shared, slots: slots, partitions: partitions)\n        royalties = Royalties.view(steps: shared, credits: credits, slots: slots, partitions: partitions)\n    }\n\n    public func annotation(shared k: Int) -> SpanAnnotation? { k < annotations.count ? annotations[k] : nil }\n\n    public func isVerified(spanIndex: Int?) -> Bool {\n        guard let spanIndex else { return false }\n        return verification[spanIndex]?.status == .verified\n    }\n\n    /// The strand a global row belongs to (its index among the current strands).\n    public func strand(ofRow row: Int) -> Int? {\n        strands.indices.first { !strands[$0].commons && row >= strands[$0].rowOffset && row < strands[$0].rowOffset + strands[$0].rowCount }\n    }\n\n    /// The Thread a global row belongs to, by name, among every strand this generation has seen.\n    public func strandName(ofRow row: Int) -> String? {\n        if let t = strand(ofRow: row) { return strands[t].name }\n        return stepSlots.lazy.flatMap { $0 }.first { $0.holds(row: row) }?.name\n    }\n\n    /// The record of the same Thread (by name) at the previous asked position, for the one-step deltas.\n    public func previousRecord(shared k: Int, strand t: Int) -> ThreadRecord? {\n        let shared = self.shared\n        let slots = sharedSlots\n        guard k < shared.count, k < slots.count, t < slots[k].count else { return nil }\n        let name = slots[k][t].name\n        var j = k - 1\n        while j >= 0 {\n            if let previous = shared[j].threads {\n                guard j < slots.count, let i = slots[j].firstIndex(where: { $0.name == name }), previous.indices.contains(i) else { return nil }\n                return previous[i]\n            }\n            j -= 1\n        }\n        return nil\n    }\n}\n\n/// The styles the detail block is drawn with; `TokenDetail.plain` uses none.\npublic struct DetailStyles {\n    public var text: Style\n    public var title: Style\n    public var dim: Style\n    public var muted: Style\n    public var gold: Style\n    public var red: Style\n    public var strand: (Int) -> Style\n\n    public init(text: Style, title: Style, dim: Style, muted: Style, gold: Style, red: Style, strand: @escaping (Int) -> Style) {\n        self.text = text\n        self.title = title\n        self.dim = dim\n        self.muted = muted\n        self.gold = gold\n        self.red = red\n        self.strand = strand\n    }\n\n    public static let plain = DetailStyles(text: .plain, title: .plain, dim: .plain, muted: .plain, gold: .plain, red: .plain, strand: { _ in .plain })\n}\n\n/// The per-token detail block, mapped one-to-one to the handoff's example:\n///\n///     token \"partition\"  ← thread: corpus-b  share 0.42  (commons 0.35, thread-a 0.23)     p 0.61  H_gate 1.04\n///                           trace: in-doc #4412  H_knn 0.81→0.77  H_lm 1.2→1.1   (shadow β4: corpus-b 0.55)\n///                           cited: corpus-b/partition-2/rows 118–121   ◉ verified\npublic enum TokenDetail {\n    public static let indent = \"                      \"\n\n    public static func f(_ x: Float, _ digits: Int = 2) -> String { String(format: \"%.\\(digits)f\", x) }\n\n    /// The three lines as plain strings (what tests pin).\n    public static func plain(_ view: GenerationView, shared k: Int, glyphs: Glyphs = .unicode) -> [String] {\n        styled(view, shared: k, styles: .plain, glyphs: glyphs).map(\\.plain)\n    }\n\n    /// The three lines, styled. The first line names the token and who supplied it, the second its\n    /// trace and the two entropies with their one-step deltas (and the shadow β4 share, muted), the\n    /// third its citation and verification.\n    public static func styled(_ view: GenerationView, shared k: Int, styles: DetailStyles, glyphs: Glyphs = .unicode) -> [Text] {\n        let shared = view.shared\n        guard k >= 0, k < shared.count, let records = shared[k].threads, !records.isEmpty else { return [] }\n        let step = shared[k]\n        let slots = k < view.sharedSlots.count ? view.sharedSlots[k] : view.strands.map(StrandSlot.init)\n        func name(_ t: Int) -> String { t < slots.count ? slots[t].name : \"strand \\(t)\" }\n        let commons = StrandSlots.commons(slots)\n        // Colours follow the Thread, not the index: its place among the current strands.\n        func colour(_ t: Int) -> Style { styles.strand(view.currentIndex(of: name(t)) ?? t) }\n        let ordered = records.indices.sorted { records[$0].share != records[$1].share ? records[$0].share > records[$1].share : $0 < $1 }\n        let lead = ordered[0]\n        let leadStyle = lead == commons ? styles.gold : colour(lead)\n\n        // Line 1: the token, who supplied it, every share, p and the gate's entropy.\n        var line1 = Text(\"token \\(step.text.debugDescription)\", style: styles.title)\n        line1.append(\"  ← \", styles.dim)\n        line1.append(lead == commons ? \"commons\" : \"thread: \\(name(lead))\", leadStyle)\n        line1.append(\"  share \\(f(records[lead].share))\", styles.text)\n        let others = ordered.dropFirst()\n        if !others.isEmpty {\n            line1.append(\"  (\", styles.dim)\n            for (i, t) in others.enumerated() {\n                if i > 0 { line1.append(\", \", styles.dim) }\n                line1.append(name(t), t == commons ? styles.gold : colour(t))\n                line1.append(\" \\(f(records[t].share))\", styles.dim)\n            }\n            line1.append(\")\", styles.dim)\n        }\n        let gateEntropy = Gate.entropy(records.map { Double($0.weight) })\n        line1.append(\"     p \\(f(step.prob))  H_gate \\(f(Float(gateEntropy)))\", styles.text)\n\n        // Line 2: the trace, the two entropies with their deltas, the shadow β4 share.\n        let record = records[lead]\n        var line2 = Text(indent, style: styles.dim)\n        if let trace = record.trace, trace.length >= TraceRule.standard.phrase, let row = trace.row {\n            let global = Int(row) + (lead < slots.count ? slots[lead].rowOffset : 0)\n            let document = view.partitions[global].map { \"…\" + $0.documentID.suffix(12) } ?? \"#\\(row)\"\n            line2.append(\"trace: in-doc \\(document) L=\\(trace.length)\", styles.text)\n        } else {\n            line2.append(\"trace: off-trace L=\\(record.trace?.length ?? 0)\", styles.dim)\n        }\n        let before = view.previousRecord(shared: k, strand: lead)\n        line2.append(\"  H_knn \\(before.map { f($0.hknn) + \"→\" } ?? \"\")\\(f(record.hknn))\", styles.text)\n        if let hlm = record.hlm { line2.append(\"  H_lm \\(before?.hlm.map { f($0) + \"→\" } ?? \"\")\\(f(hlm))\", styles.text) }\n        if lead != commons { line2.append(\"   (shadow β4: \\(name(lead)) \\(f(record.shadowShare)))\", styles.muted) }\n\n        // Line 3: the citation and its verification, or why there is none.\n        var line3 = Text(indent, style: styles.dim)\n        let annotation = view.annotation(shared: k)\n        if step.isPrompt {\n            line3.append(\"prompt token · evidence ρ̃ \", styles.dim)\n            for (i, t) in records.indices.enumerated() {\n                if i > 0 { line3.append(\", \", styles.dim) }\n                line3.append(name(t), t == commons ? styles.gold : colour(t))\n                line3.append(\" \" + (records[t].evidence.map { f($0, 1) } ?? \"—\"), styles.dim)\n            }\n        } else if let citation = annotation?.citations.first {\n            let owner = view.strandName(ofRow: citation.row)\n            let spanIndex = annotation?.spanIndex\n            let span = spanIndex.flatMap { $0 < view.spans.count ? view.spans[$0] : nil }\n            let first = span?.source.tokenOffset ?? citation.address.tokenOffset\n            let last = span.map { $0.source.tokenOffset + max(0, $0.tokens.count - 1) } ?? citation.address.tokenOffset\n            line3.append(\"cited: \", styles.dim)\n            line3.append(owner ?? (citation.address.threadID.map { String($0.prefix(8)) } ?? \"?\"), owner.flatMap { view.currentIndex(of: $0) }.map(styles.strand) ?? styles.text)\n            line3.append(\"/…\\(citation.address.documentID.suffix(12))/partition-\\(citation.address.partitionIndex)/rows \\(first)–\\(last)\", styles.text)\n            line3.append(\"   conf \\(f(citation.confidence))\", styles.dim)\n            if let spanIndex {\n                if let check = view.verification[spanIndex] {\n                    let ok = check.status == .verified\n                    line3.append(\"   \\(ok ? glyphs.verified : glyphs.cross) \\(check.status.rawValue)\", ok ? styles.gold : styles.red)\n                } else {\n                    line3.append(\"   span \\(spanIndex + 1) · v verifies\", styles.muted)\n                }\n            }\n        } else if lead == commons {\n            line3.append(\"uncited: the commons supplied it (never cited)\", styles.dim)\n        } else {\n            line3.append(\"uncited: no retrieved context predicted this token\", styles.dim)\n        }\n        return [line1, line2, line3]\n    }\n}\n"},{"path":"Sources/BraidStudio/Studio.swift","lines":98,"bytes":3650,"header":{"lines":[1,14],"what":[8,9],"pin":[10,13],"in":null,"out":null},"marks":[],"first":1781,"scopes":[["C","BackendBox",null,"final",21,22,[22,23],24,null,-1,0],["C","StreamRedirect",null,"final",27,27,[27,27],52,[26,26],-1,0],["i","init",["to"],"",30,30,[30,29],41,null,1,0],["f","restore",[],"",43,43,[43,19],51,null,1,0],["E","Studio",null,"public",54,54,[54,19],98,null,-1,0,[]],["v","isInteractive",null,"public static",58,58,[58,42],58,[57,57],4,8],["f","launch",["_"],"public static",60,61,[61,78],97,null,4,0]],"text":"//\n//  Studio.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Opens the studio: the terminal, the app loop over BraidTerminal, the live or fixture\n//        backend, and the job the first screen needs (the braid).\n//  PIN:  The UI draws on a duplicate of the terminal's descriptor while standard output and error\n//        go to <work area>/logs/studio.log, so a library that prints (a tokenizer warning, MLX,\n//        Metal) can never scribble over the screen. Both come back before the function returns,\n//        and the terminal is restored on every path out of `App.run`.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Darwin\nimport Foundation\n\n@MainActor\nfinal class BackendBox {\n    var backend: StudioBackend?\n}\n\n/// Points standard output and error at a file until `restore()`.\nfinal class StreamRedirect {\n    private var saved: [(Int32, Int32)] = []\n\n    init(to url: URL) throws {\n        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)\n        let fd = open(url.path, O_WRONLY | O_CREAT | O_APPEND, 0o644)\n        guard fd >= 0 else { throw BraidFailure(\"cannot open \\(url.path) for the studio log\", code: .exists) }\n        fflush(stdout)\n        fflush(stderr)\n        for target in [STDOUT_FILENO, STDERR_FILENO] {\n            saved.append((target, dup(target)))\n            dup2(fd, target)\n        }\n        close(fd)\n    }\n\n    func restore() {\n        fflush(stdout)\n        fflush(stderr)\n        for (target, copy) in saved {\n            dup2(copy, target)\n            close(copy)\n        }\n        saved.removeAll()\n    }\n}\n\npublic enum Studio {\n    public static let name = \"Braid studio\"\n\n    /// Standard input and output are a terminal (and not a dumb one).\n    public static var isInteractive: Bool { Terminal.isInteractive }\n\n    @MainActor\n    public static func launch(_ options: StudioOptions) async throws -> Int32 {\n        let tty = dup(STDOUT_FILENO)\n        guard tty >= 0 else { throw BraidFailure(\"cannot open the terminal\", code: .internalError) }\n        defer { close(tty) }\n        let terminal = Terminal(input: STDIN_FILENO, output: tty)\n        let logs = options.workArea?.logs ?? FileManager.default.temporaryDirectory.appendingPathComponent(\"braid\", isDirectory: true)\n        let redirect = try StreamRedirect(to: logs.appendingPathComponent(\"studio.log\"))\n        defer { redirect.restore() }\n\n        var state = StudioState(fixtures: options.fixtures != nil)\n        state.size = terminal.size\n        let box = BackendBox()\n        let app = App<StudioState, StudioEvent>(\n            display: terminal, initial: state,\n            update: { state, event in\n                let jobs = StudioApp.handle(event, state: &state)\n                for job in jobs { box.backend?.submit(job) }\n                if let code = state.quitCode { return .quit(code: code) }\n                if state.redraw {\n                    state.redraw = false\n                    return .redraw\n                }\n                return .none\n            },\n            render: { state, frame in StudioApp.render(state, &frame) })\n        let backend: StudioBackend\n        if let fixtures = options.fixtures {\n            backend = try FixtureBackend(directory: fixtures, mailbox: app.mailbox)\n        } else {\n            backend = LiveBackend(options: options, mailbox: app.mailbox)\n        }\n        box.backend = backend\n        for job in StudioApp.initialJobs(state) { backend.submit(job) }\n        let code = try await app.run()\n        await backend.shutdown()\n        return code\n    }\n}\n"},{"path":"Sources/BraidStudio/StudioApp.swift","lines":519,"bytes":27432,"header":{"lines":[1,15],"what":[8,11],"pin":[12,14],"in":null,"out":null},"marks":[[40,"Handle"],[190,"Reduce"],[302,"Render"],[403,"Overlays"]],"first":1788,"scopes":[["P","StudioScreen",null,"",21,21,[21,22],26,null,-1,0],["f","render",["_","_","_"],"static",22,22,null,22,null,0,1],["f","handle",["_","_"],"static",24,24,null,24,[23,23],0,1],["f","hints",["_"],"static",25,25,null,25,null,0,1],["E","StudioApp",null,"public",28,28,[28,22],519,null,-1,0,[]],["f","screen",["_"],"static",29,29,[29,62],35,null,4,0],["f","initialJobs",["_"],"public static",38,38,[38,72],38,[37,37],4,8],["f","handle",["_","state"],"public static",42,42,[42,100],61,null,4,0],["f","handleKey",["_","state"],"static",63,63,[63,84],86,null,4,0],["f","go",["to","state"],"public static",89,89,[89,86],97,[88,88],4,0],["f","requestQuit",["_"],"static",99,99,[99,71],106,null,4,0],["f","handleOverlay",["_","state"],"static",108,108,[108,88],175,null,4,0],["f","tick",["_","state"],"static",177,177,[177,76],188,null,4,0],["f","reduce",["_","state"],"public static",192,192,[192,93],264,null,4,0],["f","applySession",["_","state"],"static",267,267,[267,91],300,[266,266],4,0],["f","render",["_","_"],"public static",304,304,[304,74],319,null,4,0],["f","globalHints",["_"],"static",321,321,[321,63],323,null,4,0],["f","headerTitle",["_","palette"],"static",325,325,[325,76],340,null,4,0],["f","headerStatus",["_","palette","glyphs"],"static",342,342,[342,93],347,null,4,0],["f","spinner",["_","_"],"static",349,349,[349,74],351,null,4,0],["f","renderTabs",["_","_","_"],"static",353,353,[353,85],365,null,4,0],["f","renderStatus",["_","_","_"],"static",367,367,[367,87],401,null,4,0],["f","on",["_"],"",372,372,[372,41],372,null,21,12],["f","renderOverlay",["_","_","_"],"static",405,405,[405,94],463,null,4,0],["f","dialog",["_","_","_"],"static",465,465,[465,79],475,null,4,0],["f","helpLines",["_","width"],"static",477,477,[477,71],505,null,4,0],["f","hanging",["_","width"],"static",508,508,[508,60],518,[507,507],4,0]],"text":"//\n//  StudioApp.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The studio as three pure functions over `StudioState`: `handle` (a key, tick, resize,\n//        signal or backend event in, jobs out), `reduce` (backend events, the session lines among\n//        them) and `render` (the header, the three screen tabs, the screen, the key hints, the\n//        status bar and any overlay).\n//  PIN:  Pure so tests drive it without a terminal or MLX. Keys go to an open overlay first, then\n//        to a field being edited, then to the global keys, then to the screen. One shortest path\n//        per outcome: no adjacent keys or options.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\nprotocol StudioScreen {\n    static func render(_ state: StudioState, _ frame: inout Frame, _ rect: Rect)\n    /// Nil when the key means nothing on this screen.\n    static func handle(_ key: KeyEvent, _ state: inout StudioState) -> [StudioJob]?\n    static func hints(_ state: StudioState) -> [KeyHint]\n}\n\npublic enum StudioApp {\n    static func screen(_ screen: Screen) -> StudioScreen.Type {\n        switch screen {\n        case .braid: return BraidScreen.self\n        case .aii: return AIIScreen.self\n        case .doctor: return DoctorScreen.self\n        }\n    }\n\n    /// What the studio asks for as soon as it opens: the braid.\n    public static func initialJobs(_ state: StudioState) -> [StudioJob] { [.start] }\n\n    // MARK: - Handle\n\n    public static func handle(_ event: Event<StudioEvent>, state: inout StudioState) -> [StudioJob] {\n        switch event {\n        case .message(let message):\n            return reduce(message, state: &state)\n        case .tick(let date):\n            return tick(date, state: &state)\n        case .resize(let size):\n            state.size = size\n            return []\n        case .signal(let signal):\n            if signal == .interrupt { return requestQuit(&state) }\n            state.quitCode = 130\n            return [.cancel]\n        case .inputClosed:\n            state.quitCode = 0\n            return [.cancel]\n        case .key(let key):\n            return handleKey(key, state: &state)\n        }\n    }\n\n    static func handleKey(_ key: KeyEvent, state: inout StudioState) -> [StudioJob] {\n        if key == KeyEvent(.ctrl(\"c\")) { return requestQuit(&state) }\n        if state.overlay != nil { return handleOverlay(key, state: &state) }\n        if state.editing { return screen(state.screen).handle(key, &state) ?? [] }\n        state.status.error = nil\n        switch key.key {\n        case .char(let c) where (\"1\"...\"3\").contains(c) && key.modifiers.isEmpty:\n            guard let target = Screen(rawValue: Int(String(c))!) else { return [] }\n            return go(to: target, state: &state)\n        case .char(\"?\"):\n            state.overlay = .help\n            return []\n        case .char(\"q\"):\n            return requestQuit(&state)\n        case .char(\"Q\"):\n            state.quitCode = 130\n            return [.cancel]\n        case .ctrl(\"l\"):\n            state.redraw = true\n            return []\n        default:\n            return screen(state.screen).handle(key, &state) ?? []\n        }\n    }\n\n    /// Switches screens and asks for whatever the new one shows and has not loaded yet.\n    public static func go(to target: Screen, state: inout StudioState) -> [StudioJob] {\n        guard target != state.screen else { return [] }\n        state.screen = target\n        switch target {\n        case .braid: return []\n        case .aii: return state.aii.status == nil && state.status.jobs[.aii] == nil ? [.aii] : []\n        case .doctor: return !state.doctor.ran && state.status.jobs[.doctor] == nil ? [.doctor] : []\n        }\n    }\n\n    static func requestQuit(_ state: inout StudioState) -> [StudioJob] {\n        if state.fixtures || state.status.mlxJob == nil {\n            state.quitCode = 0\n            return [.cancel]\n        }\n        state.overlay = .confirmQuit\n        return []\n    }\n\n    static func handleOverlay(_ key: KeyEvent, state: inout StudioState) -> [StudioJob] {\n        guard let overlay = state.overlay else { return [] }\n        switch overlay {\n        case .help:\n            state.overlay = nil\n            return []\n        case .confirmQuit:\n            switch key.key {\n            case .char(\"y\"), .enter:\n                state.overlay = .cancelling(since: state.now)\n                state.quitAfterJobs = true\n                return [.cancel]\n            case .char(\"Q\"):\n                state.quitCode = 130\n                return [.cancel]\n            default:\n                state.overlay = nil\n                return []\n            }\n        case .cancelling:\n            if key.key == .char(\"Q\") { state.quitCode = 130 }\n            return []\n        case .picker(var picker):\n            let visible = max(1, min(picker.items.count, state.size.height - 10))\n            switch key.key {\n            case .up, .char(\"k\"): picker.table.move(by: -1, rowCount: picker.items.count, visible: visible)\n            case .down, .char(\"j\"): picker.table.move(by: 1, rowCount: picker.items.count, visible: visible)\n            case .pageUp: picker.table.page(by: -1, rowCount: picker.items.count, visible: visible)\n            case .pageDown: picker.table.page(by: 1, rowCount: picker.items.count, visible: visible)\n            case .escape, .char(\"q\"):\n                state.overlay = nil\n                return []\n            case .enter:\n                state.overlay = nil\n                guard let index = picker.table.selected, index < picker.values.count else { return [] }\n                return [.openSession(picker.values[index])]\n            default: break\n            }\n            state.overlay = .picker(picker)\n            return []\n        case .newThread(var form):\n            switch key.key {\n            case .escape:\n                state.overlay = nil\n                return []\n            case .tab, .backTab, .up, .down:\n                form.field = 1 - form.field\n            case .enter:\n                let name = form.name.text.trimmingCharacters(in: .whitespaces)\n                let corpus = form.corpus.text.trimmingCharacters(in: .whitespaces)\n                if name.isEmpty || !DocumentID.isValidHandle(name) {\n                    form.error = \"the name is a lowercase handle (letters, digits, dashes)\"\n                } else if !(corpus.hasPrefix(\"dataset:\") && corpus.contains(\"#\")) && !corpus.hasPrefix(\"dir:\") {\n                    form.error = \"the source is dataset:<name>#<node> or dir:<path>\"\n                } else if state.braid.threads.contains(where: { $0.name == name }) {\n                    form.error = \"a Thread named \\(name) exists\"\n                } else {\n                    state.overlay = nil\n                    state.status.message = \"creating \\(name) from \\(corpus): snapshot, training, index\"\n                    return [.createThread(NewThreadRequest(name: name, corpus: corpus))]\n                }\n            default:\n                if form.field == 0 ? form.name.handle(key) : form.corpus.handle(key) { form.error = nil }\n            }\n            state.overlay = .newThread(form)\n            return []\n        }\n    }\n\n    static func tick(_ date: Date, state: inout StudioState) -> [StudioJob] {\n        state.now = date\n        state.spinner &+= 1\n        if case .cancelling(let since) = state.overlay {\n            if state.status.mlxJob == nil {\n                state.quitCode = 0\n            } else if date.timeIntervalSince(since) > 15 {\n                state.quitCode = 130\n            }\n        }\n        return []\n    }\n\n    // MARK: - Reduce\n\n    public static func reduce(_ event: StudioEvent, state: inout StudioState) -> [StudioJob] {\n        switch event {\n        case .jobStarted(let kind, let label):\n            state.status.jobs[kind] = JobStatus(kind: kind, label: label, since: state.now)\n        case .jobProgress(let kind, let label):\n            state.status.jobs[kind]?.label = label\n        case .jobFinished(let kind):\n            state.status.jobs[kind] = nil\n            if kind == .generate { state.braid.generating = false }\n        case .jobFailed(let kind, let failure):\n            state.status.jobs[kind] = nil\n            if failure.code == .interrupted {\n                state.status.message = \"\\(kind.rawValue) cancelled\"\n            } else {\n                state.status.error = failure\n            }\n            state.braid.events.append(\"\\(kind.rawValue): \\(failure.message)\")\n            if kind == .generate { state.braid.generating = false }\n            if kind == .membership || kind == .createThread { state.braid.pending = [] }\n        case .log(let message):\n            state.status.message = message\n            state.braid.events.append(message)\n        case .braid(let status):\n            state.braid.status = status\n            let strands = status.strands.isEmpty ? \"no strands\" : status.strands.joined(separator: \", \")\n            state.braid.events.append(\"braid: \\(status.packName ?? \"no pack\") · \\(strands)\" + (status.seamSHA256.map { \" · tail \\($0.prefix(12))\" } ?? \"\") + (status.fixtures ? \" · fixtures\" : \"\"))\n            return [.examples]\n        case .threads(let threads):\n            state.braid.threads = threads\n            state.braid.pending = []\n            state.braid.focus = min(state.braid.focus, max(0, threads.count - 1))\n            if var status = state.braid.status {\n                status.strands = (status.commons ? [\"commons\"] : []) + threads.filter(\\.attached).map(\\.name)\n                state.braid.status = status\n            }\n        case .table(let strands, let partitions, let session):\n            state.braid.pendingStrands = strands\n            state.braid.pendingPartitions = partitions\n            if let session { state.braid.sessionURL = session }\n        case .session(let line):\n            return applySession(line, state: &state)\n        case .verified(let report):\n            state.braid.verify = report\n            if var current = state.braid.current {\n                current.verification = Dictionary(report.spans.filter { $0.generationID == current.gen.generationID }.map { ($0.span, $0) },\n                                                  uniquingKeysWith: { first, _ in first })\n                state.braid.current = current\n            }\n            let issues = report.issues.count\n            let message = \"\\(report.spansVerified)/\\(report.spans.count) spans verified\" + (issues > 0 ? \" · \\(issues) issue\\(issues == 1 ? \"\" : \"s\")\" : \"\")\n                + (report.status == .ok ? \"\" : \" · FAILED\")\n            state.status.message = message\n            state.braid.events.append(\"verify: \" + message)\n            for note in report.notes { state.braid.events.append(\"verify: \" + note) }\n        case .examples(let examples):\n            state.braid.examples = examples\n            state.braid.exampleIndex = -1\n            if !examples.isEmpty, state.braid.prompt.text.isEmpty, !state.braid.editingPrompt { BraidScreen.choose(example: 0, state: &state) }\n        case .sessions(let urls):\n            state.braid.sessions = urls\n            if urls.isEmpty {\n                state.status.message = \"no saved sessions yet: ⏎ asks the braid and writes one\"\n            } else {\n                state.overlay = .picker(Picker(title: \"Saved sessions · \\(urls.count)\", items: urls.map { $0.deletingPathExtension().lastPathComponent }, values: urls))\n            }\n        case .aii(let status):\n            state.aii.status = status\n        case .doctor(let checks):\n            state.doctor.checks = checks\n            state.doctor.ran = true\n        }\n        return []\n    }\n\n    /// A session line, live or replayed: the one path a generation renders through.\n    static func applySession(_ line: SessionLine, state: inout StudioState) -> [StudioJob] {\n        switch line {\n        case .header(let header):\n            state.braid.header = header\n            if state.braid.pendingStrands.isEmpty { state.braid.pendingStrands = header.threads }\n        case .gen(let gen):\n            let strands = state.braid.pendingStrands.isEmpty ? (state.braid.header?.threads ?? []) : state.braid.pendingStrands\n            state.braid.current = GenerationView(gen: gen, strands: strands, partitions: state.braid.pendingPartitions)\n            state.braid.generating = true\n            state.braid.cursor = 0\n            state.braid.verify = nil\n            state.braid.events.append(\"asked \\(gen.prompt.text.debugDescription) · λ \\(Theme.f(gen.params.lambda)) · \\(gen.strands.joined(separator: \", \"))\")\n        case .step(let step):\n            guard var current = state.braid.current else { return [] }\n            current.append(step)\n            state.braid.current = current\n            if state.braid.generating { state.braid.cursor = max(0, current.walkable.count - 1) }\n        case .membership(let membership):\n            // Only a running generation's strands move; a change between answers shows in the next header.\n            if state.braid.current?.isComplete == false { state.braid.current?.apply(membership) }\n            let detail = membership.kind == \"attach\" ? \" (caught up \\(membership.caughtUp) tokens in \\(Theme.f(membership.seconds, 1)) s)\" : \"\"\n            state.braid.events.append(\"\\(membership.kind) \\(membership.thread.name) at position \\(membership.position)\\(detail)\")\n        case .end(let end):\n            guard var current = state.braid.current else { return [] }\n            current.end = end\n            current.derive()\n            state.braid.current = current\n            state.braid.generating = false\n            state.braid.cursor = current.firstGenerated\n            state.braid.events.append(\"\\(end.generated) tokens · stopped on \\(end.stoppedOn?.rawValue ?? \"?\") · \\(end.generationID)\")\n            state.status.message = \"←→ walk the tokens · v verifies the spans · R royalties\"\n        }\n        return []\n    }\n\n    // MARK: - Render\n\n    public static func render(_ state: StudioState, _ frame: inout Frame) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        let (top, afterHeader) = frame.bounds.top(1)\n        CompactHeader(title: headerTitle(state, palette: palette), status: headerStatus(state, palette: palette, glyphs: glyphs),\n                      palette: palette, glyphs: glyphs).render(in: top, on: &frame.canvas)\n        let (tabsRow, afterTabs) = afterHeader.top(1)\n        renderTabs(state, &frame, tabsRow)\n        let (statusRow, aboveStatus) = afterTabs.bottom(1)\n        let (hintsRow, screenRect) = aboveStatus.bottom(1)\n        screen(state.screen).render(state, &frame, screenRect)\n        KeyHintBar(screen(state.screen).hints(state) + globalHints(state), keyStyle: palette.hintKey, labelStyle: palette.hintLabel)\n            .render(in: hintsRow, on: &frame.canvas)\n        renderStatus(state, &frame, statusRow)\n        if let overlay = state.overlay { renderOverlay(overlay, state, &frame) }\n    }\n\n    static func globalHints(_ state: StudioState) -> [KeyHint] {\n        state.editing ? [] : [KeyHint(\"1-3\", \"screens\"), KeyHint(\"?\", \"help\"), KeyHint(\"q\", \"quit\")]\n    }\n\n    static func headerTitle(_ state: StudioState, palette: Palette) -> Text {\n        var text = Text(\"\\(state.screen.rawValue) \\(state.screen.title)\", style: palette.title)\n        let detail: String?\n        switch state.screen {\n        case .braid:\n            if let status = state.braid.status {\n                detail = \"\\(status.packName ?? \"no pack\") · \\(status.strands.count) strand\\(status.strands.count == 1 ? \"\" : \"s\") · λ \\(Theme.f(state.braid.lambda))\"\n            } else {\n                detail = nil\n            }\n        case .aii: detail = state.aii.status.map { Theme.abbreviate($0.machine.path) }\n        case .doctor: detail = state.doctor.ran ? \"\\(state.doctor.checks.filter(\\.ok).count)/\\(state.doctor.checks.count) ok\" : nil\n        }\n        if let detail { text.append(\" · \" + detail, palette.dim) }\n        return text\n    }\n\n    static func headerStatus(_ state: StudioState, palette: Palette, glyphs: Glyphs) -> Text {\n        if let job = state.status.headline {\n            return Text(spinner(state, glyphs) + \" \", style: palette.orange) + Text(job.label, style: palette.dim)\n        }\n        return state.fixtures ? Text(\"fixtures\", style: palette.orange) : Text(\"v\" + state.version, style: palette.dim)\n    }\n\n    static func spinner(_ state: StudioState, _ glyphs: Glyphs) -> String {\n        glyphs.spinner[state.spinner % glyphs.spinner.count]\n    }\n\n    static func renderTabs(_ state: StudioState, _ frame: inout Frame, _ rect: Rect) {\n        let palette = frame.palette\n        let busy = Set(state.status.jobs.values.filter(\\.kind.isVisible).map { Screen.owner(of: $0.kind) })\n        let titles: [Text] = Screen.allCases.map { screen in\n            let chosen = screen == state.screen\n            var text = Text(\"\\(screen.rawValue) \", style: chosen ? palette.gold : palette.muted)\n            text.append(screen.title, chosen ? palette.blue.bold() : palette.dim)\n            if busy.contains(screen) { text.append(\" \" + spinner(state, frame.glyphs), palette.orange) }\n            return text\n        }\n        Tabs(titles, selected: state.screen.rawValue - 1, style: palette.dim, selectedStyle: palette.blue.bold(),\n             separator: Text(\"   \", style: palette.dim)).render(in: rect, on: &frame.canvas)\n    }\n\n    static func renderStatus(_ state: StudioState, _ frame: inout Frame, _ rect: Rect) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        frame.canvas.fill(rect, style: palette.selection.removing([.bold, .reverse]).fg(palette.dim.foreground))\n        let band = palette.selection.background\n        func on(_ style: Style) -> Style { band == .default ? style : style.bg(band) }\n        var left = Text(\" \", style: on(palette.dim))\n        if state.fixtures { left.append(\"fixtures  \", on(palette.orange)) }\n        if let status = state.braid.status {\n            left.append(\"braid \", on(palette.dim))\n            left.append(status.strands.isEmpty ? glyphs.idle : glyphs.live, on(status.strands.isEmpty ? palette.muted : palette.green))\n            left.append(\" \\(status.strands.count)\", on(palette.dim))\n        } else {\n            left.append(\"braid \\(glyphs.idle)\", on(palette.dim))\n        }\n        if let job = state.status.headline {\n            left.append(\"  \", on(palette.dim))\n            left.append(spinner(state, glyphs) + \" \", on(palette.orange))\n            left.append(job.label, on(palette.text))\n        } else if let area = state.braid.status?.workArea {\n            left.append(\"  \" + Theme.abbreviate(area), on(palette.muted))\n        }\n        var right = Text()\n        if let error = state.status.error {\n            right.append(\"braid: \" + error.message, on(palette.error))\n            if let hint = error.hint { right.append(\" — \" + hint, on(palette.dim)) }\n        } else if let message = state.status.message {\n            right.append(message, on(palette.dim))\n        }\n        let leftWidth = min(left.width, rect.width * 3 / 5)\n        frame.canvas.put(left.truncated(to: leftWidth), x: rect.minX, y: rect.minY, clip: rect)\n        let rightRoom = max(0, rect.width - leftWidth - 3)\n        let shown = right.truncated(to: rightRoom)\n        frame.canvas.put(shown, x: rect.maxX - shown.width - 1, y: rect.minY, clip: rect)\n    }\n\n    // MARK: - Overlays\n\n    static func renderOverlay(_ overlay: Overlay, _ state: StudioState, _ frame: inout Frame) {\n        let palette = frame.palette\n        let glyphs = frame.glyphs\n        frame.canvas.restyle(frame.bounds) { $0.adding(.dim) }\n        switch overlay {\n        case .help:\n            let width = min(frame.size.width - 4, 104)\n            let lines = helpLines(glyphs, width: width - 5)\n            let rect = frame.bounds.centered(width: width, height: min(frame.size.height - 2, lines.count + 2))\n            frame.canvas.fill(rect, style: palette.base)\n            let inner = Box(title: Text(\"Help\", style: palette.title), footer: Text(\"any key closes\", style: palette.dim),\n                            style: palette.focusBorder, glyphs: glyphs).render(in: rect, on: &frame.canvas)\n            for (row, line) in lines.prefix(inner.height).enumerated() {\n                frame.canvas.put(line.truncated(to: inner.width - 1), x: inner.minX + 1, y: inner.minY + row, clip: inner)\n            }\n        case .confirmQuit:\n            let label = state.status.headline?.label ?? \"a job\"\n            dialog(\"Quit\", [\n                Text(\"\\(label) is still running on the MLX worker.\", style: palette.text),\n                Text(\"\"),\n                Text(\"[y] cancel it and quit    [Q] quit now    [esc] stay\", style: palette.dim),\n            ], &frame)\n        case .cancelling:\n            dialog(\"Quitting\", [\n                Text(spinner(state, glyphs) + \" waiting for the running work to stop…\", style: palette.orange),\n                Text(\"\"),\n                Text(\"[Q] quit now\", style: palette.dim),\n            ], &frame)\n        case .picker(let picker):\n            let width = min(frame.size.width - 8, max(50, (picker.items.map(\\.count).max() ?? 20) + 10))\n            let height = min(frame.size.height - 6, picker.items.count + 2)\n            let rect = frame.bounds.centered(width: width, height: max(3, height))\n            frame.canvas.fill(rect, style: palette.base)\n            let inner = Box(title: Text(picker.title, style: palette.title), footer: Text(\"⏎ replay  esc close\", style: palette.dim),\n                            style: palette.focusBorder, glyphs: glyphs).render(in: rect, on: &frame.canvas)\n            Table.styled(columns: [Column(\"\", .flex(1))], rows: picker.items.map { [Text($0)] }, state: picker.table,\n                         palette: palette, glyphs: glyphs, showHeader: false).render(in: inner, on: &frame.canvas)\n        case .newThread(let form):\n            let notes = [\n                Text(\"The source is a dataset node, dataset:<name>#<node> (braid-n3#ambient), or a folder of .txt files, dir:<path>.\", style: palette.dim),\n                Text(\"The Thread is snapshotted, its own blocks 0–11 trained in front of the commons' tail, indexed, made live and attached — the braid thread create path.\", style: palette.dim),\n            ] + (form.error.map { [Text(\"\\(glyphs.cross) \\($0)\", style: palette.red)] } ?? [])\n            let rect = frame.bounds.centered(width: min(frame.size.width - 4, 100), height: notes.count + 7)\n            frame.canvas.fill(rect, style: palette.base)\n            let inner = Box(title: Text(\"New Thread\", style: palette.title), footer: Text(\"tab next field  ⏎ create  esc cancel\", style: palette.dim),\n                            style: palette.focusBorder, glyphs: glyphs).render(in: rect, on: &frame.canvas)\n            frame.cursor = nil\n            for (row, (label, field, focused)) in [(\"name\", form.name, form.field == 0), (\"source\", form.corpus, form.field == 1)].enumerated() {\n                let y = inner.minY + 1 + row\n                frame.canvas.put(label, x: inner.minX + 2, y: y, style: focused ? palette.title : palette.dim, clip: inner)\n                let fieldRect = Rect(x: inner.minX + 10, y: y, width: max(0, inner.width - 12), height: 1)\n                TextField(state: field, placeholder: row == 0 ? \"a lowercase handle\" : \"dataset:<name>#<node>\", focused: focused, style: palette.title,\n                          placeholderStyle: palette.muted, cursorStyle: palette.cursor).render(in: fieldRect, on: &frame.canvas)\n            }\n            for (row, note) in notes.enumerated() {\n                frame.canvas.put(note.truncated(to: inner.width - 4), x: inner.minX + 2, y: inner.minY + 4 + row, clip: inner)\n            }\n        }\n    }\n\n    static func dialog(_ title: String, _ lines: [Text], _ frame: inout Frame) {\n        let palette = frame.palette\n        let width = min(frame.size.width - 4, max(40, (lines.map(\\.width).max() ?? 30) + 6))\n        let rect = frame.bounds.centered(width: width, height: lines.count + 4)\n        frame.canvas.fill(rect, style: palette.base)\n        let inner = Box(title: Text(title, style: palette.title), style: palette.focusBorder, glyphs: frame.glyphs)\n            .render(in: rect, on: &frame.canvas)\n        for (row, line) in lines.enumerated() {\n            frame.canvas.put(line, x: inner.minX + 2, y: inner.minY + 1 + row, clip: inner)\n        }\n    }\n\n    static func helpLines(_ glyphs: Glyphs, width: Int = 94) -> [Text] {\n        let sections: [(String, [(String, String)])] = [\n            (\"screens\", [(\"1 Braid\", \"the braid: ask, walk the tokens, attach and detach Threads\"), (\"2 AII\", \"the machine's AII and the demo AIIs\"), (\"3 Doctor\", \"the checks braid doctor runs\")]),\n            (\"braid\", [(\"/ p\", \"type a prompt\"), (\"⏎\", \"ask\"), (\"tab ⇧tab\", \"focus a Thread\"), (\"space\", \"attach or detach it\"), (\"n\", \"new Thread\"),\n                       (\"R\", \"royalties: shares or credit\"), (\"←→\", \"walk the tokens\"), (\"v\", \"verify the spans\"), (\"o\", \"open a saved session\"),\n                       (\"x\", \"next example prompt\"), (\"r\", \"Q/A on or off\"), (\"t\", \"likeliest or sampled\"), (\"- +\", \"λ\"), (\"c\", \"cancel\")]),\n            (\"aii\", [(\"r\", \"refresh\")]),\n            (\"doctor\", [(\"r\", \"run the checks again\")]),\n            (\"global\", [(\"1-3\", \"screens\"), (\"?\", \"this help\"), (\"^L\", \"redraw\"), (\"q\", \"quit\"), (\"Q\", \"quit now\")]),\n        ]\n        var lines: [Text] = []\n        for (title, entries) in sections {\n            var line = Text(title.padding(toLength: 10, withPad: \" \", startingAt: 0), style: .plain)\n            for (key, label) in entries {\n                line.append(\"[\" + key + \"] \", .plain)\n                line.append(label + \"   \", .plain)\n            }\n            lines.append(contentsOf: hanging(line, width: width))\n        }\n        lines.append(Text(\"\"))\n        for line in [\n            \"tokens    coloured by the strand that supplied ≥ 0.6 of them · gold = the commons · off-white = shared · dim = uncited · underlined = verified span · reverse = cursor\",\n            \"detail    token «…» ← who supplied it, every share, p, H_gate · trace in-doc/off-trace, H_knn and H_lm with their one-step deltas, the shadow β4 share (never applied) · the citation\",\n            \"legend    \\(glyphs.check) ok  \\(glyphs.cross) fail  \\(glyphs.live) attached  \\(glyphs.idle) detached  \\(glyphs.spinner[0]) busy  \\(glyphs.verified) verified  \\(glyphs.select) focused\",\n            \"\",\n            \"cli       braid doctor · init · import · pack · thread create|list|show · cluster spawn · verify · ui --fixtures <dir>\",\n        ] { lines.append(contentsOf: hanging(Text(line), width: width)) }\n        return lines\n    }\n\n    /// Wraps with a 10-column hanging indent under the section label.\n    static func hanging(_ line: Text, width: Int) -> [Text] {\n        guard !line.isEmpty else { return [line] }\n        let first = Paragraph.wrap(line, width: max(20, width))\n        guard first.count > 1 else { return first }\n        var result = [first[0]]\n        let remainder = first.dropFirst().reduce(Text()) { $0 + Text(\" \") + $1 }\n        for piece in Paragraph.wrap(remainder, width: max(10, width - 10)) {\n            result.append(Text(\"          \") + piece)\n        }\n        return result\n    }\n}\n"},{"path":"Sources/BraidStudio/StudioEvents.swift","lines":230,"bytes":7947,"header":{"lines":[1,14],"what":[8,11],"pin":[12,13],"in":null,"out":null},"marks":[],"first":1815,"scopes":[["E","JobKind",null,"public",19,19,[19,52],37,null,-1,0,["start","generate","membership","createThread","examples","verify","sessions","openSession","aii","doctor"]],["v","isMLX",null,"public",23,23,[23,27],28,[22,22],0,0],["v","isVisible",null,"public",31,31,[31,31],36,[30,30],0,0],["S","GenerateRequest",null,"public",39,39,[39,51],55,null,-1,0],["i","init",["prompt","lambda","temperature","maxTokens","question"],"public",48,48,[48,122],54,null,3,0],["S","NewThreadRequest",null,"public",57,57,[57,52],66,null,-1,0],["i","init",["name","corpus"],"public",62,62,[62,46],65,null,5,0],["E","StudioJob",null,"public",68,68,[68,32],104,null,-1,0,["start","generate","attach","detach","createThread","examples","verify","sessions","openSession","aii","doctor","cancel"]],["v","kind",null,"public",89,89,[89,30],103,null,7,0],["S","BraidStatus",null,"public",107,107,[107,47],129,[106,106],-1,0],["i","init",["fixtures","workArea","packName","packSHA256","strands","commons","sessionsDirectory","seamSHA256"],"public",119,119,[119,177],128,null,9,0],["S","ThreadSummary",null,"public",132,132,[132,49],148,[131,131],-1,0],["i","init",["name","label","source","version","attached","error"],"public",140,140,[140,117],147,null,11,0],["S","ExamplePrompt",null,"public",151,151,[151,49],163,[150,150],-1,0],["i","init",["thread","label","prompt","expected"],"public",157,157,[157,81],162,null,13,0],["S","AIIHomeStatus",null,"public",166,166,[166,49],189,[165,165],-1,0],["i","init",["name","path","layout","lanes","stackSecret","httpPort","grpcPort","health","healthProblem"],"public",178,178,[178,167],188,null,15,0],["S","AIIStatus",null,"public",191,191,[191,45],201,null,-1,0],["i","init",["machine","demoRoot","demos"],"public",196,196,[196,82],200,null,17,0],["E","SessionLine",null,"public",204,204,[204,34],210,[203,203],-1,0,["header","gen","step","end","membership"]],["E","StudioEvent",null,"public",212,212,[212,34],230,null,-1,0,["jobStarted","jobProgress","jobFinished","jobFailed","log","braid","threads","table","session","verified","examples","sessions","aii","doctor"]]],"text":"//\n//  StudioEvents.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What the UI asks the backend to do (jobs) and what the backend reports back (events).\n//        Both are Sendable values; the UI never touches a model, a file or a socket. A session\n//        reaches the screen as its log lines (`StudioEvent.session`), so a live generation and a\n//        replayed one render through one path.\n//  PIN:  MLX jobs (start, generate, attach/detach, create a Thread) run one at a time on the MLX\n//        worker's thread; the rest (AII, doctor, sessions, verify, examples) run as detached tasks.\n//\n\nimport BraidKit\nimport Foundation\n\npublic enum JobKind: String, Sendable, CaseIterable {\n    case start, generate, membership, createThread, examples, verify, sessions, openSession, aii, doctor\n\n    /// Runs on the MLX worker, one at a time.\n    public var isMLX: Bool {\n        switch self {\n        case .start, .generate, .membership, .createThread: return true\n        default: return false\n        }\n    }\n\n    /// Worth a spinner in the status bar.\n    public var isVisible: Bool {\n        switch self {\n        case .sessions, .examples, .aii: return false\n        default: return true\n        }\n    }\n}\n\npublic struct GenerateRequest: Sendable, Equatable {\n    public var prompt: String\n    public var lambda: Float\n    public var temperature: Float\n    public var maxTokens: Int\n    /// The prompt is a question (ends in \"?\" while Q/A is on): the commons rewrites it into a stem, each\n    /// Thread completes it behind its own context, and the answer is one sentence.\n    public var question: Bool\n\n    public init(prompt: String, lambda: Float = 0.5, temperature: Float = 0, maxTokens: Int = 24, question: Bool = false) {\n        self.prompt = prompt\n        self.lambda = lambda\n        self.temperature = temperature\n        self.maxTokens = maxTokens\n        self.question = question\n    }\n}\n\npublic struct NewThreadRequest: Sendable, Equatable {\n    public var name: String\n    /// `dataset:<name>#<node>` (or `dir:<path>`), the grammar `braid thread create --corpus` takes.\n    public var corpus: String\n\n    public init(name: String, corpus: String) {\n        self.name = name\n        self.corpus = corpus\n    }\n}\n\npublic enum StudioJob: Sendable {\n    /// Load the pack, the commons and the Threads braid.toml attaches; build the cluster.\n    case start\n    case generate(GenerateRequest)\n    /// Attach or detach a Thread at the next token boundary (now, when no generation runs).\n    case attach(String)\n    case detach(String)\n    case createThread(NewThreadRequest)\n    /// Fact prompts from the attached Threads' dataset nodes.\n    case examples\n    /// Replay a session log against the Threads' snapshots and index layouts.\n    case verify(URL)\n    /// List `sessions/*.jsonl`.\n    case sessions\n    /// Replay a saved session into the screen.\n    case openSession(URL)\n    case aii\n    case doctor\n    /// Stop the running generation at the next token boundary.\n    case cancel\n\n    public var kind: JobKind? {\n        switch self {\n        case .start: return .start\n        case .generate: return .generate\n        case .attach, .detach: return .membership\n        case .createThread: return .createThread\n        case .examples: return .examples\n        case .verify: return .verify\n        case .sessions: return .sessions\n        case .openSession: return .openSession\n        case .aii: return .aii\n        case .doctor: return .doctor\n        case .cancel: return nil\n        }\n    }\n}\n\n/// The braid as the worker assembled it.\npublic struct BraidStatus: Sendable, Equatable {\n    public var fixtures: Bool\n    public var workArea: String?\n    public var packName: String?\n    public var packSHA256: String?\n    /// The strands attached, in the cluster's order (the commons first when present).\n    public var strands: [String]\n    public var commons: Bool\n    public var sessionsDirectory: URL?\n    /// The seam of the commons' tail, the one every Thread runs; nil in fixture mode.\n    public var seamSHA256: String?\n\n    public init(fixtures: Bool, workArea: String?, packName: String?, packSHA256: String?, strands: [String], commons: Bool, sessionsDirectory: URL?, seamSHA256: String? = nil) {\n        self.fixtures = fixtures\n        self.workArea = workArea\n        self.packName = packName\n        self.packSHA256 = packSHA256\n        self.strands = strands\n        self.commons = commons\n        self.sessionsDirectory = sessionsDirectory\n        self.seamSHA256 = seamSHA256\n    }\n}\n\n/// One Thread in the work area, attached or not.\npublic struct ThreadSummary: Sendable, Equatable {\n    public var name: String\n    public var label: String\n    public var source: String\n    public var version: String?\n    public var attached: Bool\n    public var error: String?\n\n    public init(name: String, label: String, source: String, version: String?, attached: Bool, error: String? = nil) {\n        self.name = name\n        self.label = label\n        self.source = source\n        self.version = version\n        self.attached = attached\n        self.error = error\n    }\n}\n\n/// A fact prompt from a Thread's dataset node: the prompt, and the answer its document holds.\npublic struct ExamplePrompt: Sendable, Equatable {\n    public var thread: String\n    public var label: String\n    public var prompt: String\n    public var expected: String\n\n    public init(thread: String, label: String, prompt: String, expected: String) {\n        self.thread = thread\n        self.label = label\n        self.prompt = prompt\n        self.expected = expected\n    }\n}\n\n/// One AII home as detected: the machine's (`home`) or a demo under <repo>/aii.\npublic struct AIIHomeStatus: Sendable, Equatable {\n    public var name: String\n    public var path: String\n    public var layout: Bool\n    public var lanes: [String]\n    public var stackSecret: Bool\n    public var httpPort: Int?\n    public var grpcPort: Int?\n    /// \"healthy · stack proof · contract 1\" when the Thread answered.\n    public var health: String?\n    public var healthProblem: String?\n\n    public init(name: String, path: String, layout: Bool, lanes: [String], stackSecret: Bool, httpPort: Int?, grpcPort: Int?, health: String?, healthProblem: String?) {\n        self.name = name\n        self.path = path\n        self.layout = layout\n        self.lanes = lanes\n        self.stackSecret = stackSecret\n        self.httpPort = httpPort\n        self.grpcPort = grpcPort\n        self.health = health\n        self.healthProblem = healthProblem\n    }\n}\n\npublic struct AIIStatus: Sendable, Equatable {\n    public var machine: AIIHomeStatus\n    public var demoRoot: String\n    public var demos: [AIIHomeStatus]\n\n    public init(machine: AIIHomeStatus, demoRoot: String, demos: [AIIHomeStatus]) {\n        self.machine = machine\n        self.demoRoot = demoRoot\n        self.demos = demos\n    }\n}\n\n/// A session log line, as written (live) or as read back (replay).\npublic enum SessionLine: Sendable {\n    case header(SessionHeader)\n    case gen(GenerationLine)\n    case step(Step)\n    case end(EndLine)\n    case membership(MembershipLine)\n}\n\npublic enum StudioEvent: Sendable {\n    case jobStarted(JobKind, String)\n    case jobProgress(JobKind, String)\n    case jobFinished(JobKind)\n    case jobFailed(JobKind, BraidFailure)\n    /// A line for the Events pane and the status bar.\n    case log(String)\n    case braid(BraidStatus)\n    case threads([ThreadSummary])\n    /// The strands and the braid's partition table a generation is logged against (live: the\n    /// cluster's; replay: the end line's), and the file the session is written to or read from.\n    case table(strands: [SessionThread], partitions: [PartitionRef], session: URL?)\n    case session(SessionLine)\n    case verified(VerifyReport)\n    case examples([ExamplePrompt])\n    case sessions([URL])\n    case aii(AIIStatus)\n    case doctor([DoctorCheck])\n}\n"},{"path":"Sources/BraidStudio/StudioState.swift","lines":175,"bytes":5537,"header":{"lines":[1,11],"what":[8,10],"pin":null,"in":null,"out":null},"marks":[],"first":1836,"scopes":[["E","Screen",null,"public",17,17,[17,48],36,null,-1,0,["braid","aii","doctor"]],["v","title",null,"public",20,20,[20,29],26,null,0,0],["f","owner",["of"],"public static",29,29,[29,57],35,[28,28],0,0],["S","Picker",null,"public",38,38,[38,31],50,null,-1,0],["i","init",["title","items","values","table"],"public",44,44,[44,108],49,null,3,0],["S","NewThreadForm",null,"public",53,53,[53,38],61,[52,52],-1,0],["i","init",[],"public",60,60,[60,18],60,null,5,8],["E","Overlay",null,"public",63,63,[63,30],69,null,-1,0,["help","picker","newThread","confirmQuit","cancelling"]],["S","JobStatus",null,"public",71,71,[71,45],75,null,-1,0],["S","StatusState",null,"public",77,77,[77,36],89,null,-1,0],["v","headline",null,"public",83,83,[83,36],86,[82,82],9,0],["v","mlxJob",null,"public",88,88,[88,34],88,null,9,8],["E","RoyaltiesPane",null,"public",91,91,[91,47],91,null,-1,8,[]],["S","BraidScreenState",null,"public",94,94,[94,41],136,[93,93],-1,0],["i","init",[],"public",124,124,[124,18],124,null,13,8],["v","focusedThread",null,"public",126,126,[126,45],126,null,13,8],["v","ready",null,"public",129,129,[129,27],129,[128,128],13,8],["v","example",null,"public",132,132,[132,39],135,[131,131],13,0],["S","AIIScreenState",null,"public",138,138,[138,39],141,null,-1,0],["i","init",[],"public",140,140,[140,18],140,null,18,8],["S","DoctorScreenState",null,"public",143,143,[143,42],147,null,-1,0],["i","init",[],"public",146,146,[146,18],146,null,20,8],["S","StudioState",null,"public",149,149,[149,36],175,null,-1,0],["i","init",["fixtures","version"],"public",165,165,[165,79],168,null,22,0],["v","editing",null,"public",171,171,[171,29],174,[170,170],22,0]],"text":"//\n//  StudioState.swift\n//  BraidStudio\n//\n//  Created by Ritesh Pakala.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Everything the studio shows, as one value: the screen and any overlay, the status bar,\n//        the braid (its Threads, the generation on the screen and the cursor in it), the AII and\n//        the doctor readings.\n//\n\nimport BraidKit\nimport BraidTerminal\nimport Foundation\n\npublic enum Screen: Int, CaseIterable, Sendable {\n    case braid = 1, aii, doctor\n\n    public var title: String {\n        switch self {\n        case .braid: return \"Braid\"\n        case .aii: return \"AII\"\n        case .doctor: return \"Doctor\"\n        }\n    }\n\n    /// The screen a job's progress shows on.\n    public static func owner(of kind: JobKind) -> Screen {\n        switch kind {\n        case .aii: return .aii\n        case .doctor: return .doctor\n        default: return .braid\n        }\n    }\n}\n\npublic struct Picker: Sendable {\n    public var title: String\n    public var items: [String]\n    public var values: [URL]\n    public var table: TableState\n\n    public init(title: String, items: [String], values: [URL], table: TableState = TableState(selected: 0)) {\n        self.title = title\n        self.items = items\n        self.values = values\n        self.table = table\n    }\n}\n\n/// The new-Thread dialog: a name and a corpus source, ⏎ creates it, esc leaves.\npublic struct NewThreadForm: Sendable {\n    public var name = TextFieldState(\"\")\n    public var corpus = TextFieldState(\"dataset:\")\n    /// 0 the name, 1 the source.\n    public var field = 0\n    public var error: String?\n\n    public init() {}\n}\n\npublic enum Overlay: Sendable {\n    case help\n    case picker(Picker)\n    case newThread(NewThreadForm)\n    case confirmQuit\n    case cancelling(since: Date)\n}\n\npublic struct JobStatus: Sendable, Equatable {\n    public var kind: JobKind\n    public var label: String\n    public var since: Date\n}\n\npublic struct StatusState: Sendable {\n    public var jobs: [JobKind: JobStatus] = [:]\n    public var message: String?\n    public var error: BraidFailure?\n\n    /// The job the status bar shows: the MLX job first, then any visible one.\n    public var headline: JobStatus? {\n        jobs.values.filter { $0.kind.isMLX }.sorted { $0.since < $1.since }.first\n            ?? jobs.values.filter { $0.kind.isVisible }.sorted { $0.since < $1.since }.first\n    }\n\n    public var mlxJob: JobStatus? { jobs.values.first { $0.kind.isMLX } }\n}\n\npublic enum RoyaltiesPane: Sendable, Equatable { case shares, credit }\n\n/// The braid screen: the Threads, the generation shown (streaming or done) and the cursor in it.\npublic struct BraidScreenState: Sendable {\n    public var status: BraidStatus?\n    public var header: SessionHeader?\n    public var threads: [ThreadSummary] = []\n    /// Into `threads`.\n    public var focus = 0\n    /// Threads with an attach or detach in flight.\n    public var pending: Set<String> = []\n    /// The table the next `gen` line is logged against.\n    public var pendingStrands: [SessionThread] = []\n    public var pendingPartitions: [PartitionRef] = []\n    public var current: GenerationView?\n    public var generating = false\n    /// Into `current.walkable`.\n    public var cursor = 0\n    public var prompt = TextFieldState(\"\")\n    public var editingPrompt = false\n    public var examples: [ExamplePrompt] = []\n    public var exampleIndex = -1\n    public var royalties: RoyaltiesPane = .shares\n    public var lambda: Float = 0.5\n    public var temperature: Float = 0\n    /// A typed prompt ending in \"?\" goes through the stem adapter (r toggles; a flag until the question path lands).\n    public var questions = true\n    public var events = LogState(capacity: 400)\n    /// The log the generation shown is written to or was read from.\n    public var sessionURL: URL?\n    public var sessions: [URL] = []\n    public var verify: VerifyReport?\n\n    public init() {}\n\n    public var focusedThread: ThreadSummary? { focus < threads.count ? threads[focus] : nil }\n\n    /// Whether the braid has strands to ask.\n    public var ready: Bool { !(status?.strands.isEmpty ?? true) }\n\n    /// The example whose prompt the field holds, if the text is still its own.\n    public var example: ExamplePrompt? {\n        guard exampleIndex >= 0, exampleIndex < examples.count, examples[exampleIndex].prompt == prompt.text else { return nil }\n        return examples[exampleIndex]\n    }\n}\n\npublic struct AIIScreenState: Sendable {\n    public var status: AIIStatus?\n    public init() {}\n}\n\npublic struct DoctorScreenState: Sendable {\n    public var checks: [DoctorCheck] = []\n    public var ran = false\n    public init() {}\n}\n\npublic struct StudioState: Sendable {\n    public var fixtures: Bool\n    public var version: String\n    public var screen: Screen = .braid\n    public var overlay: Overlay?\n    public var status = StatusState()\n    public var braid = BraidScreenState()\n    public var aii = AIIScreenState()\n    public var doctor = DoctorScreenState()\n    public var size = Size(width: 120, height: 40)\n    public var now = Date()\n    public var spinner = 0\n    public var quitCode: Int32?\n    public var quitAfterJobs = false\n    public var redraw = false\n\n    public init(fixtures: Bool = false, version: String = BraidVersion.string) {\n        self.fixtures = fixtures\n        self.version = version\n    }\n\n    /// A text field is taking keystrokes: global keys are off.\n    public var editing: Bool {\n        if case .newThread = overlay { return true }\n        return screen == .braid && braid.editingPrompt\n    }\n}\n"}]};
